#version 300 es
#define SHADER_NAME section-rgb-fragment
precision mediump float;

precision highp float;
precision highp int;

in vec2 vUV;
in vec3 vSection;
in vec4 vColor;

in highp vec2 vCtrl;
in highp vec2 vSamp;
flat in highp vec4 vKC0;
flat in highp vec4 vKC1;
flat in highp vec4 vKG0;
#ifdef K_ROOT
flat in highp vec4 vKR0;
in vec3 vKRC;
in vec3 vKRO;
flat in vec3 vKRJ;
#endif


out vec4 finalColor;


