highp vec4 kS(int i) { return texelFetch(uKStatic, ivec2(i & 1023, i >> 10), 0); }
highp vec4 kG(int i) { return texelFetch(uKGeom, ivec2(i & 1023, i >> 10), 0); }
highp vec4 kR(int i) { return texelFetch(uKReveal, ivec2(i & 1023, i >> 10), 0); }
