struct KChain {
  int ch;
  int nCtrl;
  bool closed;
  int count;
  int idx;
  int geom;
  int src0;
  int srcN;
  float total;
  float arcPer;
  float fxDone;
  bool paintOn;
};

KChain kChainOf(int ch, highp vec4 a, highp vec4 b, highp vec4 g) {
  KChain c;
  c.ch = ch;
  c.nCtrl = int(a.x + 0.5);
  c.closed = a.y > 0.5;
  c.count = int(a.z + 0.5);
  c.idx = int(a.w + 0.5);
  c.geom = int(b.x + 0.5);
  c.src0 = int(b.y + 0.5);
  c.srcN = int(b.z + 0.5);
  c.total = g.x;
  c.arcPer = g.y;
  c.fxDone = g.z;
  c.paintOn = g.w > 0.5;
  return c;
}

KChain kChain(int ch) {
  highp vec4 a = kS(2 * ch);
  highp vec4 b = kS(2 * ch + 1);
  return kChainOf(ch, a, b, kG(int(b.x + 0.5)));
}

// Control i's arc (i in [0, nCtrl)).
highp float kCA(KChain c, int i) {
  highp vec4 t = kG(c.geom + 1 + (i >> 2));
  int j = i & 3;
  return j == 0 ? t.x : j == 1 ? t.y : j == 2 ? t.z : t.w;
}

// K299: floor(fl / n) EXACTLY, for an integer-valued fl and n > 0 (a ring's
// lap). GPU float division is approximate (GLSL ES allows 2.5 ULP; ANGLE's
// D3D11 path multiplies by a reciprocal): on an RX 6800 XT floor(28.0 /
// 28.0) came out 0, and floor(k n / n) came out k - 1 for a fifth of (k, n).
// A lap one short put the slot index one past the chain's arc table, into
// the next chain's header: a closed chain's run ending at its seam drew its
// pulse and trail at a garbage arc. The quotient is within one of the
// truth, so one integer step corrects it.
int kLapOf(highp float fl, int n) {
  int k = int(floor(fl / float(n)));
  int r = int(fl) - k * n;
  return r < 0 ? k - 1 : r >= n ? k + 1 : k;
}

// x wrapped into [0, m) for m > 0, whatever the division's rounding (K299).
highp float kWrap(highp float x, highp float m) {
  highp float r = x - m * floor(x / m);
  if (r < 0.0) r += m;
  if (r >= m) r -= m;
  return r;
}

// A closed ring's arc of ctrl x within x's lap, in [0, total] (total only
// where the slot's fraction rounds to its end); the lap goes to kRingLap.
int kRingLap;
highp float kRingArc(KChain c, highp float x) {
  int n = c.nCtrl;
  highp float fl = floor(x);
  kRingLap = kLapOf(fl, n);
  int i0 = int(fl) - n * kRingLap;
  highp float a0 = kCA(c, i0);
  highp float a1 = i0 + 1 < n ? kCA(c, i0 + 1) : c.total;
  return a0 + (a1 - a0) * (x - fl);
}

// The renderer's paintArcAt: closed rings wrap, open chains clamp the slot
// (ctrl < 0 extrapolates to a negative arc, as on the CPU).
highp float kArcOfCtrl(KChain c, highp float x) {
  int n = c.nCtrl;
  if (c.closed) {
    highp float a = kRingArc(c, x);
    return a >= c.total ? a - c.total : a;
  }
  int i = clamp(int(floor(x)), 0, n - 1);
  highp float a0 = kCA(c, i);
  highp float a1 = i + 1 < n ? kCA(c, i + 1) : c.total;
  return min(c.total, a0 + (a1 - a0) * (x - float(i)));
}

// Monotone unwrapped arc of an unwrapped ctrl.
highp float kArcU(KChain c, highp float x) {
  if (!c.closed) return kArcOfCtrl(c, x);
  highp float a = kRingArc(c, x);
  return a + c.total * float(kRingLap);
}

// The bake's arc -> ctrl map, by binary search (vertex stage; 13 steps
// cover 8192 controls).
highp float kCtrlOfArc(KChain c, highp float a) {
  int lo = 0;
  int hi = c.nCtrl - 1;
  for (int it = 0; it < 14; it++) {
    if (lo >= hi) break;
    int m = (lo + hi + 1) >> 1;
    if (kCA(c, m) <= a) lo = m;
    else hi = m - 1;
  }
  highp float a0 = kCA(c, lo);
  highp float a1 = lo < c.nCtrl - 1 ? kCA(c, lo + 1) : c.total;
  return float(lo) + (a1 > a0 ? min(1.0, (a - a0) / (a1 - a0)) : 0.0);
}

// kCtrlOfArc's exact answer (the largest slot whose arc is <= a) by a short
// walk from a nearby ctrl; the binary search when the walk would be long.
highp float kCtrlOfArcNear(KChain c, highp float a, highp float seed) {
  int n = c.nCtrl;
  int s = clamp(int(floor(seed)), 0, n - 1);
  bool ok = false;
  for (int it = 0; it < 8; it++) {
    if (s < n - 1 && kCA(c, s + 1) <= a) { s++; continue; }
    if (s > 0 && kCA(c, s) > a) { s--; continue; }
    ok = true;
    break;
  }
  if (!ok) return kCtrlOfArc(c, a);
  highp float a0 = kCA(c, s);
  highp float a1 = s < n - 1 ? kCA(c, s + 1) : c.total;
  return float(s) + (a1 > a0 ? min(1.0, (a - a0) / (a1 - a0)) : 0.0);
}

// The exact ctrl at arc a from an approximate one (fragment stage: the
// interpolated vertex ctrl is off by a fraction of a slot where a control
// breakpoint falls inside a quad): ring-aware slot walk, then the clamped
// fraction.
highp float kCtrlNear(KChain c, highp float a, highp float approx) {
  int n = c.nCtrl;
  int s = int(floor(approx));
  if (c.closed) s -= n * kLapOf(float(s), n);
  else s = clamp(s, 0, n - 1);
  highp float a0 = 0.0;
  highp float a1 = 0.0;
  for (int it = 0; it < 6; it++) {
    a0 = kCA(c, s);
    a1 = s + 1 < n ? kCA(c, s + 1) : c.total;
    highp float d = a - a0;
    if (c.closed) d -= c.total * floor(d / c.total + 0.5);
    if (d < 0.0) {
      if (!c.closed && s == 0) break;
      s = s == 0 ? n - 1 : s - 1;
    } else if (d >= a1 - a0) {
      if (!c.closed && s == n - 1) break;
      s = s + 1 == n ? 0 : s + 1;
    } else {
      break;
    }
  }
  highp float d = a - a0;
  if (c.closed) d -= c.total * floor(d / c.total + 0.5);
  highp float t = a1 > a0 ? clamp(d / (a1 - a0), 0.0, 1.0) : 0.0;
  return float(s) + t;
}



highp float kSmooth(highp float x) {
  highp float c = clamp(x, 0.0, 1.0);
  return c * c * (3.0 - 2.0 * c);
}

highp float kRainbowP(highp float age) {
  return age >= RAINBOW_HOLD + RAINBOW_FADE
    ? 0.0
    : 1.0 - kSmooth((age - RAINBOW_HOLD) / RAINBOW_FADE);
}

highp float kMaterialize(highp float age, int style) {
  highp float e = style == 3 ? DUST_FADE_IN : COMET_FADE_IN;
  return age >= e ? 1.0 : kSmooth(age / e);
}



struct KIgn {
  bool hit;
  float tA;
  float cFrom;
  float dir;
  float t0;
  float rate;
  float tEnd;
  float span;
};

KIgn kIgnition(KChain c, highp float ctrl) {
  KIgn r;
  r.hit = false;
  r.tA = 1e9;
  r.cFrom = 0.0;
  r.dir = 1.0;
  r.t0 = 0.0;
  r.rate = 1.0;
  r.tEnd = 0.0;
  r.span = 0.0;
  int n = c.nCtrl;
  int sl = clamp(int(floor(ctrl)), 0, n - 1);
  highp vec4 I = kS(c.idx + sl);
  if (uKInk.y > 0.5) {
    int j = c.closed ? (sl + 1 == n ? 0 : sl + 1) : min(sl + 1, n - 1);
    highp float b = kS(c.idx + j).w;
    r.hit = true;
    r.tA = I.w + (b - I.w) * (ctrl - float(sl));
    return r;
  }
  if (I.y < -0.5) return r;
  // The slot's hint: its first touching source + (count - 1) / 8.
  int s0 = int(I.y);
  int cnt = int(fract(I.y) * 8.0 + 0.5) + 1;
  for (int k = 0; k < 4; k++) {
    if (k >= cnt) break;
    int s = s0 + k;
    if (s >= c.src0 + c.srcN) break;
    highp vec4 A = kR(2 * s);
    if (ctrl < A.x - 1e-4 || ctrl > A.y + 1e-4) continue;
    highp vec4 B = kR(2 * s + 1);
    highp float t = B.x + abs(ctrl - A.z) / B.y;
    // Near-ties (fronts leaving one junction, or meeting) go to the first
    // source scanned: an f32 ctrl must not flip the choice the CPU makes.
    if (t < r.tA - 1e-4) {
      r.hit = true;
      r.tA = t;
      r.cFrom = A.z;
      r.dir = A.w;
      r.t0 = B.x;
      r.rate = B.y;
      r.tEnd = B.z;
      r.span = B.w;
    }
  }
  return r;
}

highp float kWall(highp float tA) {
  highp vec4 k = uKKnots[0];
  for (int i = 1; i < 8; i++) {
    highp vec4 q = uKKnots[i];
    if (q.w < 0.5 || q.x > tA) break;
    k = q;
  }
  return k.y + (tA - k.x) * k.z;
}

highp float kFxTail(int st) {
  highp float t = st == 1 ? RAINBOW_HOLD + RAINBOW_FADE
    : st == 2 ? COMET_FADE_IN
    : st == 3 ? DUST_FADE_IN
    : BURN_RECOVER_END;
  return t + 0.02;
}

// The anim time the burn's hot head leaves a point (paint_math kHeadLeave).
highp float kHeadLeave(KChain c, KIgn g, highp float ctrl) {
  highp float aU = kArcU(c, ctrl) + g.dir * BURN_HOT_ARC;
  highp float ch;
  if (c.closed) {
    highp float n = float(c.nCtrl);
    highp float lap = floor(aU / c.total);
    highp float seed = lap > 0.0 ? 0.0 : lap < 0.0 ? n - 1.0 : ctrl - n * floor(ctrl / n);
    ch = kCtrlOfArcNear(c, aU - lap * c.total, seed) + lap * n;
  } else {
    ch = kCtrlOfArcNear(c, clamp(aU, 0.0, c.total), ctrl);
  }
  highp float t = g.t0 + g.dir * (ch - g.cFrom) / g.rate;
  return max(g.tA, min(g.tEnd, t));
}

highp float kBurnAge(KChain c, KIgn g, highp float ctrl) {
  return max(0.0, uKFx.z - kWall(kHeadLeave(c, g, ctrl)));
}

vec3 kBurn(vec3 rgb, highp float t, highp float k, bool roots) {
  if (t >= BURN_RECOVER_END) return rgb;
  if (roots) {
    highp float brown = 1.0 - kSmooth((t - ROOTS_START) / ROOTS_FADE);
    if (brown > 0.004) rgb += (vec3(0.35, 0.25, 0.18) - rgb) * brown;
    return rgb;
  }
  highp float heatW = 1.0 - kSmooth((t - 0.015) / 0.05);
  highp float heatY = kSmooth(t / 0.02) * (1.0 - kSmooth((t - 0.1) / 0.12));
  highp float ember = kSmooth(t / 0.08) * (1.0 - kSmooth((t - BURN_EMBER_END) / 0.25));
  highp float chr = kSmooth((t - BURN_EMBER_END * 0.55) / 0.25) *
    (1.0 - kSmooth((t - BURN_CHAR_END) / (BURN_RECOVER_END - BURN_CHAR_END)));
  rgb += (vec3(0.14, 0.11, 0.1) - rgb) * (chr * 0.92);
  if (ember > 0.01) {
    highp float spatial = 1.0 - chr;
    highp float fl = 0.5 +
      spatial * (0.3 * sin(uKFx2.x + k * 0.31) + 0.2 * sin(uKFx2.y + k * 0.83)) +
      (1.0 - spatial) * uKFx2.w;
    highp float e = ember * 0.85 * (1.0 - heatW * 0.7);
    rgb += (vec3(1.0 - 0.3 * fl, 0.54 - 0.35 * fl, 0.16 - 0.08 * fl) - rgb) * e;
  }
  if (heatY > 0.001) rgb += (vec3(1.0, 0.84, 0.3) - rgb) * heatY;
  if (heatW > 0.001) rgb += (vec3(1.0, 0.97, 0.88) - rgb) * heatW;
  return rgb;
}

// RAINBOW: p = appearance progress (1 = just appeared -> 0 = recovered).
// Sequence along a fading point: full stripes (6 bands across the ribbon,
// side = vUV.y), then a brief FADED WHITE wash, then the true section
// color - the two windows overlap so every handoff is a crossfade.
vec3 kRainbowBlend(vec3 base, highp float pIn, highp float side) {
  highp float p = min(pIn, 1.0);
  int bi = int(min(side, 0.99999) * 6.0);
  vec3 stripe = bi == 0 ? vec3(0.92, 0.15, 0.18)
    : bi == 1 ? vec3(1.0, 0.55, 0.08)
    : bi == 2 ? vec3(1.0, 0.88, 0.12)
    : bi == 3 ? vec3(0.12, 0.78, 0.3)
    : bi == 4 ? vec3(0.15, 0.42, 1.0)
    : vec3(0.58, 0.25, 0.95);
  highp float rb = smoothstep(0.30, 0.52, p);
  highp float wh = smoothstep(0.06, 0.26, p) * (1.0 - smoothstep(0.38, 0.60, p));
  base = mix(base, stripe, rb);
  return mix(base, vec3(0.93, 0.93, 0.95), wh * 0.6);
}

// FX applied to a material's color at a ribbon point (burn / roots tint;
// rainbow progress and materialize alpha come back through the outs).
// Revealed points only - the caller passes the ctrl and sample position.
vec3 kFxColor(KChain c, highp float ctrl, highp float kSample, vec3 rgb,
    out highp float pRain, out highp float alpha) {
  pRain = 0.0;
  alpha = 1.0;
  int st = int(uKFx.x + 0.5);
  if (uKFx.w < 0.5 || st == 0 || uKFx.z >= c.fxDone) return rgb;
  // A SETTLED SLOT (CTRLIDX .w = its latest source finish): identity.
  if (uKInk.y < 0.5) {
    int sl = clamp(int(floor(ctrl)), 0, c.nCtrl - 1);
    if (uKFx.z >= kWall(kS(c.idx + sl).w) + kFxTail(st)) return rgb;
  }
  KIgn g = kIgnition(c, ctrl);
  if (!g.hit || uKFx.y < g.tA) {
    // Ahead of the front (the tip taper's leading edge): materializing
    // styles stay transparent there, the rest wear no effect yet.
    if (st == 2 || st == 3) alpha = 0.0;
    return rgb;
  }
  if (st == 4 || st == 5) return kBurn(rgb, kBurnAge(c, g, ctrl), kSample, st == 5);
  highp float age = uKFx.z - kWall(g.tA);
  if (st == 1) pRain = kRainbowP(age);
  else alpha = kMaterialize(age, st);
  return rgb;
}


// The pulse trains' reach window (K75): full strength out to reach - fade
// from the junction, smoothly gone at reach. The hover stops there too
// (K93).
highp float kReachWin(highp float d) {
  highp float f = max(uKReach.y, 1e-4);
  return 1.0 - kSmooth((d - (uKReach.x - f)) / f);
}
// K111 stage 4 (K265): High contrast's highlight prototype, uKBase.y. 0 =
// today's pulses: every prototype branch is skipped and the paint is
// master's. 1 contrast, 2 outline, 3 chevrons (kComposePaintAcross). The
// CPU mirror draws the pulses whatever the id (prototypes skip parity,
// K152 (3); the picked look gets its mirror in stage 5).
int kHcLook() {
  return int(uKBase.y + 0.5);
}

// Brightness at global distance dG; bumpK scales the crest trains (1 on
// the arms and the fan's bands, 0 in a strip's quiet row). A High
// contrast prototype has no trains and no breath: one steady level out
// to the reach (the looks shape it; prototypes skip mirror parity).
highp float kPulseCrestK(highp float dG, bool inward, bool hovered, highp float endWin, highp float bumpK) {
  if (kHcLook() != 0) return endWin * uKPulse.w * kReachWin(dG);
  if (hovered) return endWin * uKPaint.w * kReachWin(dG);
  highp float s = uKPulse.z;
  highp float raw = inward ? dG + uKPulse.x : dG - uKPulse.y;
  highp float ph = raw - s * floor(raw / s);
  highp float dist = min(ph, s - ph);
  highp float dC = max(0.0, dG - (ph <= s - ph ? ph : ph - s));
  highp float bump = max(0.0, 1.0 - dist / CREST_WIDTH) * min(1.0, dC / CREST_RAMP) * bumpK;
  highp float fl = (PULSE_FLOOR + PULSE_CORE_BOOST * max(0.0, 1.0 - dG / PULSE_CORE_RADIUS)) *
    max(0.0, 1.0 - dG / PULSE_FLOOR_REACH);
  return min(1.0, (fl + bump * 0.9) * endWin) * uKPulse.w * kReachWin(dG);
}
highp float kPulseCrest(highp float dG, bool inward, bool hovered, highp float endWin) {
  return kPulseCrestK(dG, inward, hovered, endWin, 1.0);
}
highp float kPulseCrestQuiet(highp float dG, bool inward, bool hovered, highp float endWin) {
  return kPulseCrestK(dG, inward, hovered, endWin, 0.0);
}

// kReachWin, kHcLook and the crest itself live in PULSE_CREST_GLSL
// (above), which paintCore prepends: the fan shader includes that chunk
// without the paint items.
highp float kGoldU(highp float p) {
  return p >= 1.0 ? 121.0 / 256.0 : p <= 0.0 ? 115.0 / 256.0 : (115.0 + 6.0 * p) / 256.0;
}

// The choice band's pulse distance (world arc from the junction) and pixel
// size at this pixel, for the chevrons (kPaintAt sets them with st.z).
highp float kHcD;
highp float kHcPx;
// K137 fray (4.3's look, prototype; mirror/parity wait for Levi's pick):
// the strongest FRAY item's coverage at this pixel. SECTION_FRAG (the
// ribbons) narrows and desaturates on it; other programs ignore it.
highp float kFrayHere = 0.0;
highp float kTele = 0.0;
uniform vec4 uKTeleAt;
highp float kPulseV(highp float d, highp float span, bool inward, bool hovered, highp float dist0, bool cont) {
  if (d < 0.0 || d > span) return 0.0;
  highp float endWin = cont ? 1.0 : clamp((span - d) / PULSE_END_WINDOW, 0.0, 1.0);
  return kPulseCrest(dist0 + d, inward, hovered, endWin);
}
// K1139 S4: lit from both ends; trains fade to the floor at the ridge.
highp float kPulseV2(highp float d, highp float span, highp float dA, highp float dB, bool inA, bool inB, bool hov, highp float bK) {
  if (d < 0.0 || d > span) return 0.0;
  highp float gA = dA + d;
  highp float gB = dB + span - d;
  bK *= min(1.0, abs(gA - gB) * 1.0000);
  bool sA = gA <= gB;
  return kPulseCrestK(sA ? gA : gB, sA ? inA : inB, hov, 1.0, bK);
}

highp float kRingDist(highp float a, highp float b, highp float total, bool closed) {
  highp float d = abs(a - b);
  return closed ? min(d, total - d) : d;
}

highp float kCov(highp float sd, highp float px) {
  if (!(px > 0.0)) return sd >= 0.0 ? 1.0 : 0.0;
  return clamp(sd / px + 0.5, 0.0, 1.0);
}

// The hover glow across the ribbon (K145, K111 stage 3; side = vUV.y, the
// edges at 0 and 1): 1 at either edge, fading out smoothly to 0 at the
// hoverGlowWidth param's share of the half-width in from it (K111 stage 4,
// K264). The width arrives as a scale on RIM_EDGE (its default), not as a
// divisor: at the default the scale is exactly 1, so the shader divides by
// the same constant as before the slider, however a compiler folds it.
highp float kRimAcross(highp float side) {
  highp float e = abs(2.0 * side - 1.0);
  return 1.0 - kSmooth((1.0 - e) / RIM_EDGE * uKGold.w);
}

// K813: the telegraph rims' own across shape (uKHlHover.w = 1 /
// telegraphWidth, so 1 reads exactly as the rims did at the default).
highp float kTeleAcross(highp float side) {
  highp float e = abs(2.0 * side - 1.0);
  return 1.0 - kSmooth((1.0 - e) / RIM_EDGE * uKHlHover.w);
}

// (p, band, v, rim): the gold ramp amount, a pulse band and its strength,
// and the hover glow along the thread (K145; kRimAcross shapes it across).
highp vec4 kPaintAt(KChain c, highp float ctrl, highp float arc, highp float px, bool quiet) {
  highp vec4 st = vec4(0.0);
  kFrayHere = 0.0;
  if (uKPaint.x < 0.5) return st;
  int n = c.nCtrl;
  int sl = clamp(int(floor(ctrl)), 0, n - 1);
  highp vec4 I = kP(c.idx + sl);
  int first = int(I.x + 0.5);
  int cnt = int(I.y + 0.5);
  highp float total = c.total;
  int refBase = int(uKPaint.y + 0.5);
  int itemBase = int(uKPaint.z + 0.5);
  for (int k = 0; k < 32; k++) {
    if (k >= cnt) break;
    int r = first + k;
    highp vec4 rt = kP(refBase + (r >> 2));
    int j = r & 3;
    int item = int((j == 0 ? rt.x : j == 1 ? rt.y : j == 2 ? rt.z : rt.w) + 0.5);
    highp vec4 T0 = kP(itemBase + 2 * item);
    highp vec4 T1 = kP(itemBase + 2 * item + 1);
    int type = int(T0.x + 0.5);
    if (type == PI_SPAN) {
      highp float a0 = kArcOfCtrl(c, T0.y);
      highp float a1 = kArcOfCtrl(c, T0.z);
      bool wraps = c.closed && a1 <= a0 && T0.z > T0.y;
      bool inside = wraps ? (arc >= a0 || arc <= a1) : (arc >= a0 && arc <= a1);
      highp float dEdge = min(kRingDist(arc, a0, total, c.closed), kRingDist(arc, a1, total, c.closed));
      highp float cov = kCov(inside ? dEdge : -dEdge, px);
      if (cov <= 0.0) continue;
      highp float p = 1.0;
      if (T0.w < 1.0 || T1.x < 1.0) {
        highp float spanLen = max(wraps ? total - a0 + a1 : a1 - a0, 1e-9);
        highp float da = wraps && arc < a0 ? total - a0 + arc : arc - a0;
        p = T0.w + (T1.x - T0.w) * clamp(da / spanLen, 0.0, 1.0);
      }
      st.x += (p - st.x) * cov;
    } else if (type == PI_CAP) {
      highp float pc = T0.w;
      if (!(kGoldU(pc) > kGoldU(st.x))) continue;
      highp float d = kRingDist(arc, kArcOfCtrl(c, T0.y), total, c.closed);
      highp float cov = kCov(T1.z - d, px);
      if (cov <= 0.0) continue;
      st.x += (pc - st.x) * cov;
    } else if (type == PI_PULSE) {
      int flags = int(T1.y + 0.5);
      highp float aJ = kArcOfCtrl(c, T0.y);
      highp float aF = kArcOfCtrl(c, T0.z);
      bool dirPos;
      highp float span;
      if (c.closed) {
        // Unwrapped (K299): a run that goes once around has span = total.
        dirPos = T0.z > T0.y;
        highp float uJ = kArcU(c, T0.y);
        highp float uF = kArcU(c, T0.z);
        span = dirPos ? uF - uJ : uJ - uF;
      } else {
        dirPos = aF >= aJ;
        span = abs(aF - aJ);
      }
      if (span <= 1e-6) continue;
      highp float d;
      if (c.closed) {
        d = kWrap(dirPos ? arc - aJ : aJ - arc, total);
      } else {
        d = dirPos ? arc - aJ : aJ - arc;
      }
      bool inwP = (flags & IF_INWARD) != 0;
      bool hovP = (flags & IF_HOVER) != 0;
      highp float v = (flags & 8) != 0
        ? kPulseV2(d, span, T0.w, T1.w, inwP, (flags & 16) != 0, hovP, quiet ? 0.0 : 1.0)
        : quiet
        ? (d < 0.0 || d > span
            ? 0.0
            : kPulseCrestQuiet(T0.w + d, inwP, hovP, T1.z > 0.5 ? 1.0 : clamp((span - d) / PULSE_END_WINDOW, 0.0, 1.0)))
        : kPulseV(d, span, inwP, hovP, T0.w, T1.z > 0.5);
      if (v > PULSE_MIN_V) {
        // 2 = a hovered choice under a High contrast prototype (K111 stage
        // 4), which the looks draw apart; anything over 0.5 is a band.
        st.y = kHcLook() != 0 && (flags & IF_HOVER) != 0 ? 2.0 : 1.0;
        st.z = v;
        kHcD = d;
        kHcPx = px;
      }
    } else if (type == PI_RIM) {
      highp float u0 = kArcU(c, T0.y);
      highp float u1 = kArcU(c, T0.z);
      highp float u = arc;
      if (c.closed) u = u0 + kWrap(arc - u0, total);
      if (u < u0 || u > u1) continue;
      // K298: its own length (uKSect.z, not the pulses' reach) and end
      // fade (uKSect.w, not the fixed RIM_END_FADE).
      highp float d = abs(u - kArcU(c, uKReach.w));
      highp float dEnd = min(u - u0, u1 - u);
      highp float fade = clamp(RIM_END_SHARE * (0.5 * (u1 - u0) - T0.w), 1e-4, max(uKSect.w, 1e-4));
      highp float g = uKReach.z * (1.0 - kSmooth(d / max(uKSect.z, 1e-4))) *
        kSmooth((dEnd - T0.w) / fade);
      st.w = max(st.w, g);
    } else if (type == 10) {
      highp float fa0 = kArcOfCtrl(c, T0.y);
      highp float fa1 = kArcOfCtrl(c, T0.z);
      bool fWraps = c.closed && fa1 <= fa0 && T0.z > T0.y;
      bool fInside = fWraps ? (arc >= fa0 || arc <= fa1) : (arc >= fa0 && arc <= fa1);
      highp float fEdge = min(kRingDist(arc, fa0, total, c.closed), kRingDist(arc, fa1, total, c.closed));
      highp float fCov = kCov(fInside ? fEdge : -fEdge, px);
      if (fCov > 0.0) kFrayHere = max(kFrayHere, fCov * T0.w);
    } else if (type == 9) {
      highp float u0 = kArcU(c, T1.z < 0.0 ? uKTeleAt.x : T0.y);
      highp float u1 = kArcU(c, T1.w < 0.0 ? uKTeleAt.x : T0.z);
      highp float u = c.closed ? u0 + kWrap(arc - u0, total) : arc;
      if (u < u0 || u > u1) continue;
      highp float hl = 0.5 * (u1 - u0);
      highp float f0 = clamp(RIM_END_SHARE * (hl - T1.x), 1e-4, max(abs(T1.z), 1e-4));
      highp float f1 = clamp(RIM_END_SHARE * (hl - T1.y), 1e-4, max(abs(T1.w), 1e-4));
      kTele = max(kTele, T0.w * min(kSmooth((u - u0 - T1.x) / f0), kSmooth((u1 - u - T1.y) / f1)));
    }
  }
  return st;
}

highp float kGlow(KChain c, highp float ctrl) {
  // Palette mode only (knot mode marks its tips with discs), interval
  // modes only, never under burn / roots (their tint IS the frontier).
  if (uKBase.w < 0.5 || uKFx2.z < 0.5 || uKInk.y > 0.5) return 0.0;
  int stl = int(uKFx.x + 0.5);
  if (stl == 4 || stl == 5) return 0.0;
  highp float t = uKFx.y;
  int n = c.nCtrl;
  int sl = clamp(int(floor(ctrl)), 0, n - 1);
  highp float hint = kS(c.idx + sl).y;
  if (hint < -0.5) return 0.0;
  int s0 = int(hint);
  int cnt = int(fract(hint) * 8.0 + 0.5) + 1;
  highp float glowArc = uKShape.z;
  highp float hold = uKShape.w;
  highp float aU = kArcU(c, ctrl);
  highp float g = 0.0;
  for (int k = 0; k < 4; k++) {
    if (k >= cnt) break;
    int s = s0 + k;
    if (s >= c.src0 + c.srcN) break;
    highp vec4 A = kR(2 * s);
    if (ctrl < A.x - 1e-4 || ctrl > A.y + 1e-4) continue;
    highp vec4 B = kR(2 * s + 1);
    highp float prog = (t - B.x) * B.y;
    if (prog <= 0.0 || prog >= B.w) continue;
    highp float tA = B.x + abs(ctrl - A.z) / B.y;
    if (t < tA) continue;
    highp float d = abs(kArcU(c, A.z + A.w * prog) - aU);
    if (d > glowArc) continue;
    g = max(g, d <= hold ? 1.0 : 1.0 - (d - hold) / (glowArc - hold));
  }
  return g;
}

// The paint over section S: the gold ramp gives the thread's own paint
// color (traveled gold, a trail fade, a cap), then a pulse band or the
// reveal glow (the stronger) brightens THAT color toward white. K75: the
// retired strip picked a band FAMILY per pulse arm (gold -> white on
// traveled arms, S -> white elsewhere), so an inbound crest on a fading
// trail drew gold bands over the faded thread; composed this way a crest
// meets the thread's paint at its edges whatever the paint is. Where the
// paint is pure gold or pure section color (gold mode) it equals the old
// bands.
vec3 kComposePaint(vec3 S, highp vec4 st, highp float glow) {
  vec3 under = S + (uKGold.rgb - S) * clamp(st.x, 0.0, 1.0);
  highp float band = st.y > 0.5 ? st.z : 0.0;
  highp float v = max(band, glow);
  // K813: the band brightens toward the pulse color (white, as today,
  // unless pulseColor says otherwise); the reveal glow keeps white.
  vec3 tgt = band >= glow ? uKHlPulse.rgb : vec3(1.0);
  return under + (tgt - under) * (K_BAND * clamp(v, 0.0, 1.0));
}

// The hover glow over a painted color (K298): the same whitening as a
// band's, applied after the paint, so a hovered choice shows both. Over a
// color kComposePaint whitened by nothing it is exactly that whitening.
vec3 kRimOver(vec3 c, highp float rim) {
  // K813: toward the hover color (white, as today, by default).
  return c + (uKHlHover.rgb - c) * (K_BAND * clamp(rim, 0.0, 1.0));
}


// A High contrast prototype's choice (K111 stage 4): the paint goes toward
// the pattern's gray "white" (0 black, 1 white) by the band's strength,
// whatever its hue, and the reveal glow brightens the result as in
// kComposePaint.
vec3 kHcCompose(vec3 S, highp vec4 st, highp float glow, highp float white) {
  vec3 under = S + (uKGold.rgb - S) * clamp(st.x, 0.0, 1.0);
  highp float v = clamp(st.z, 0.0, 1.0);
  vec3 c = under + (vec3(white) - under) * v;
  return c + (vec3(1.0) - c) * (K_BAND * clamp(glow, 0.0, 1.0));
}


// The paint on a RIBBON (side = vUV.y, the edges at 0 and 1):
// kComposePaint, except a choice under a High contrast prototype (K111
// stage 4). 1 CONTRAST: white with a black center line. 2 OUTLINE: a black
// core between white edges. 3 CHEVRONS: black and white chevrons pointing
// away from the junction. A hovered choice is solid white under each; the
// hover rim composes over the result (kRimOver, K298).
vec3 kComposePaintAcross(vec3 S, highp vec4 st, highp float glow, highp float side) {
  int look = kHcLook();
  if (look == 0 || st.y < 0.5) return kComposePaint(S, st, glow);
  if (st.y > 1.5) return kHcCompose(S, st, glow, 1.0);
  highp float e = abs(2.0 * side - 1.0);
  highp float white;
  if (look == 1) {
    white = clamp((e - HC_LINE) / HC_LINE_SOFT + 0.5, 0.0, 1.0);
  } else if (look == 2) {
    white = clamp((e - HC_CORE) / HC_CORE_SOFT + 0.5, 0.0, 1.0);
  } else {
    highp float u = (kHcD - HC_CHEV_LEAN * (1.0 - e)) / HC_CHEV_PERIOD;
    highp float sd = (0.25 - abs(fract(u) - 0.5)) * HC_CHEV_PERIOD;
    white = clamp(sd / max(kHcPx, 1e-4) + 0.5, 0.0, 1.0);
  }
  return kHcCompose(S, st, glow, white);
}

uniform vec4 uKTele;
vec3 kTeleOver(vec3 c, highp float t) {
  return c + (uKTele.rgb - c) * clamp(t, 0.0, 1.0);
}



// x = arc along the chain, y = approximate ctrl (refine with kCtrlNear).
highp vec2 kFragPoint(KChain c) {
  highp vec2 cw = fwidth(vCtrl);
  highp vec2 sw = fwidth(vSamp);
  highp float cf = cw.y < 0.5 * cw.x ? vCtrl.y : vCtrl.x;
  highp float sf = sw.y < 0.5 * sw.x ? vSamp.y : vSamp.x;
  highp float arc = c.closed
    ? fract(sf) * c.total
    : min(sf * float(c.count) * c.arcPer, c.total);
  highp float ctrl = c.closed ? fract(cf) * float(c.nCtrl) : cf * float(c.nCtrl);
  return vec2(arc, ctrl);
}
KChain kFragChain() {
  return kChainOf(int(vKC1.w + 0.5), vKC0, vKC1, vKG0);
}


#ifdef K_ROOT
vec3 kRootSection(highp float a, highp float pxW) {
  int kt = int(vKR0.x + 0.5) - 1;
  highp float u = clamp(a / vKR0.z, 0.0, 1.0);
  highp float nr = kG(kt).z;
  highp float f = u * (nr - 1.0);
  int i0 = min(int(nr + 0.5) - 2, int(floor(f)));
  int ea = kt + 2 + 2 * i0;
  highp float hw = mix(kG(ea).z, kG(ea + 2).z, f - float(i0));
  highp float covC = clamp(0.5 + (vUV.y - 0.5) * vKR0.y * 2.0 * hw / pxW, 0.0, 1.0);
  highp float w = u + (u * u * (3.0 - 2.0 * u) - u) * uKSect.y;
  return mix(mix(vKRO, vKRC, covC), vKRJ, w);
}
#endif


uniform highp sampler2D uG3Chain;
vec4 g3ChainAt(int chain, int part) {
  int t = chain * 2 + part;
  return texelFetch(uG3Chain, ivec2(t & 1023, t >> 10), 0);
}


in highp vec2 vPos;
in highp float vTurnA;
in highp float vTurnB;
in highp vec2 vTan;
flat in highp vec4 vMaskId;

uniform highp sampler2D uGapData;

uniform highp sampler2D uSamp;
uniform vec4 uFabricGap;
vec2 sampAt(int i) {
  int t = i >> 1;
  vec4 q = texelFetch(uSamp, ivec2(t & 1023, t >> 10), 0);
  return (i & 1) == 0 ? q.xy : q.zw;
}



void gapSeg(highp vec2 p, highp vec2 a, highp vec2 b, int k,
    inout highp float best, inout int bk) {
  highp vec2 ab = b - a;
  highp vec2 pa = p - a;
  highp float l2 = dot(ab, ab);
  highp float h = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
  highp vec2 q = pa - ab * h;
  highp float d2 = dot(q, q);
  if (d2 < best) {
    best = d2;
    bk = k;
  }
}

// FULL: also skips segment indices skipLo..skipHi (the far-branch pass;
// empty when skipLo > skipHi) and, when ex > 0 (self-crossings), a segment
// whose nearest point's chain arc lies within ex of the fragment's arc fa
// (s0/st: the range's arc parameterization in sampled steps; per: the
// ring period, 0 on open chains).
void gapSegFull(highp vec2 p, highp vec2 a, highp vec2 b, int k,
    highp float ex, highp float fa, highp float s0, highp float st,
    highp float per, int skipLo, int skipHi,
    inout highp float best, inout int bk) {
  if (k >= skipLo && k <= skipHi) return;
  highp vec2 ab = b - a;
  highp vec2 pa = p - a;
  highp float l2 = dot(ab, ab);
  highp float h = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
  if (ex > 0.0) {
    highp float da = s0 + (float(k) + h) * st - fa;
    if (per > 0.0) da -= per * floor(da / per + 0.5);
    if (abs(da) < ex) return;
  }
  highp vec2 q = pa - ab * h;
  highp float d2 = dot(q, q);
  if (d2 < best) {
    best = d2;
    bk = k;
  }
}

ivec4 gapRange(vec4 t4, vec4 t9) {
  return ivec4(int(t4.y + 0.5), max(int(t9.x + 0.5), 1),
    max(int(t9.y + 0.5), 1), int(floor(t4.z + 0.5)));
}
highp vec2 gapAt(int r, out int i, ivec4 g, bool ring) {
  i = ring ? ((r % g.z) + g.z) % g.z : clamp(r, 0, g.z - 1);
  return sampAt(g.x + i);
}
highp vec2 gapNext(inout int r, inout int i, ivec4 g, bool ring) {
  r += g.y;
  i += g.y;
  i = ring ? (i < g.z ? i : i - g.z) : clamp(r, 0, g.z - 1);
  return sampAt(g.x + i);
}

// Sampled point j of a range (t4 = [selfExcl, overBase, kStart, arcPer],
// t9 = [stride, count, closed, -]): rings wrap, open chains clamp (never
// a last-to-first chord).
vec2 gapOverPt(vec4 t4, vec4 t9, int j) {
  ivec4 g = gapRange(t4, t9);
  int i;
  return gapAt(g.w + j * g.y, i, g, t9.z > 0.5);
}

// Nearest point of the sampled range within sqrt(best) (best is the
// squared reach on entry); the nearest segment (-1: none within reach)
// comes back through bk. Fast form: no exclusions.
void gapNearestFast(int row, int nCh, highp vec2 p,
    highp float sure2, highp vec4 t4, highp vec4 t9, int nPts,
    inout highp float best, inout int bk) {
  bool brute = uFabricGap.z > 0.5;
  int nSeg = max(nPts - 1, 0);
  ivec4 g = gapRange(t4, t9);
  bool ring = t9.z > 0.5;
  for (int c = 0; c < 8; c++) {
    if (c >= nCh) break;
    if (!brute && best < sure2) break;
    int k0 = c * 8;
    if (!brute) {
      highp vec4 cc = texelFetch(uGapData, ivec2(10 + c, row), 0);
      highp float lb = length(p - cc.xy) - cc.z;
      if (lb > 0.0 && lb * lb >= best) continue;
    }
    int r = g.w + k0 * g.y, i;
    highp vec2 a = gapAt(r, i, g, ring);
    for (int j = 0; j < 8; j++) {
      int k = k0 + j;
      if (k >= nSeg) break;
      highp vec2 b = gapNext(r, i, g, ring);
      gapSeg(p, a, b, k, best, bk);
      a = b;
    }
  }
}

void gapNearestFull(int row, int nCh, highp vec2 p,
    highp float ex, highp float fa, highp float s0, highp float st,
    highp float per, int skipLo, int skipHi,
    highp float sure2, highp vec4 t4, highp vec4 t9, int nPts,
    inout highp float best, inout int bk) {
  bool brute = uFabricGap.z > 0.5;
  int nSeg = max(nPts - 1, 0);
  ivec4 g = gapRange(t4, t9);
  bool ring = t9.z > 0.5;
  for (int c = 0; c < 8; c++) {
    if (c >= nCh) break;
    if (!brute && best < sure2) break;
    int k0 = c * 8;
    // A chunk wholly inside the skipped index range adds nothing.
    if (!brute && k0 >= skipLo && min(k0 + 7, nSeg - 1) <= skipHi) {
      continue;
    }
    if (!brute) {
      highp vec4 cc = texelFetch(uGapData, ivec2(10 + c, row), 0);
      highp float lb = length(p - cc.xy) - cc.z;
      if (lb > 0.0 && lb * lb >= best) continue;
    }
    int r = g.w + k0 * g.y, i;
    highp vec2 a = gapAt(r, i, g, ring);
    for (int j = 0; j < 8; j++) {
      int k = k0 + j;
      if (k >= nSeg) break;
      highp vec2 b = gapNext(r, i, g, ring);
      gapSegFull(p, a, b, k, ex, fa, s0, st, per, skipLo, skipHi, best, bk);
      a = b;
    }
  }
}
bool gapProbe() {
  return uFabricGap.y > 0.5;
}


// A slot's effective strength (texel 1.w; see the header): gated slots
// ramp in from their show time on the knot clock (uKFx.z = fxNow); with the
// FX clock stopped (uKFx.w = 0) every gate has long opened. Needs the knot
// uniforms and CROSSING_FADE_IN (paint_glsl.ts) declared first.
highp float gapStrength(highp float s) {
  if (s >= 0.0) return s;
  if (uKFx.w < 0.5) return 1.0;
  highp float x = clamp((uKFx.z + s + 1.0) / CROSSING_FADE_IN, 0.0, 1.0);
  return x * x * (3.0 - 2.0 * x);
}

// 1 inside the arc interval [a, b] (with a short ramp), 0 outside; an
// empty interval (a >= b) is 0.
highp float gapInterval(highp float o, highp float a, highp float b) {
  if (a >= b) return 0.0;
  return clamp(min(o - a, b - o) / 0.04 + 0.5, 0.0, 1.0);
}

// How much of p lies over the ribbon (half-width h) around a PROTECT
// range in SAMP (G3-1): 1 inside, a one-pixel ramp at its edge, 0 outside
// (and for fewer than 2 sampled points). The range texel at base is
// [sampBase, kStart, nPts, stride] and the next texel its bounding circle
// [cx, cy, r, signedCount] (negative = the chain is closed, |.| = its
// sample count, for the wrap). Loop-free: the circle rejects most
// fragments, then ONE segment loop reads the samples in place - no chunk
// nesting (G1's protect cost was mostly register pressure, so the loop
// stays single).
highp float gapProtCover(int row, int base, highp vec2 p,
    highp float h, highp float pxW) {
  highp vec4 rg = texelFetch(uGapData, ivec2(base, row), 0);
  int n = int(rg.z + 0.5);
  if (n < 2) return 0.0;
  highp vec4 bc = texelFetch(uGapData, ivec2(base + 1, row), 0);
  highp float reach = h + pxW;
  highp float rr = bc.z + reach;
  highp vec2 dc = p - bc.xy;
  if (dot(dc, dc) > rr * rr) return 0.0;
  int r = int(floor(rg.y + 0.5)), i;
  ivec4 g = ivec4(int(rg.x + 0.5), max(int(rg.w + 0.5), 1),
    max(int(abs(bc.w) + 0.5), 1), 0);
  bool ring = bc.w < -0.5;
  highp vec2 a = gapAt(r, i, g, ring);
  highp float best = reach * reach;
  for (int j = 0; j < 64; j++) {
    if (j >= n - 1) break;
    highp vec2 b = gapNext(r, i, g, ring);
    highp vec2 ab = b - a;
    highp vec2 pa = p - a;
    highp float l2 = dot(ab, ab);
    highp float hh = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
    highp vec2 q = pa - ab * hh;
    best = min(best, dot(q, q));
    a = b;
  }
  return clamp((h - sqrt(best)) / pxW + 0.5, 0.0, 1.0);
}

highp float gapKeepAt(highp float pxW, highp vec2 p, highp float turn,
    highp vec2 tanv, highp vec4 ids) {
  if (all(lessThan(abs(ids + 1.0), vec4(0.5)))) return 1.0;
  if (uFabricGap.x < 0.5) return 1.0;
  // Every slot of a ribbon fragment windows the fragment's own chain, so
  // one turn serves them all.
  bool fan = false;
  highp float keep = 1.0;
  for (int s = 0; s < 4; s++) {
    // Fully hidden already: no later slot can change the answer.
    if (keep <= 0.002) break;
    highp float idf = ids[s];
    if (abs(idf + 1.0) < 0.5) continue; // -1 = no slot.
    // ids >= 0: the full mask (ribbons; a fan that IS the under thread's
    // material - a free tip's cap). ids <= -2 encode slot (-id - 2) for a
    // JUNCTION fan: the over silhouette only (see below).
    bool full = idf > -0.5;
    int row = int(full ? idf + 0.5 : -idf - 1.5) + 1;
    // REJECT on texel 0 alone: the bounding circle grown by the reach of
    // interest (a disabled slot's radius is negative).
    highp vec4 t0 = texelFetch(uGapData, ivec2(0, row), 0);
    highp float rr = full ? t0.z + 2.0 * pxW : t0.w + pxW;
    highp vec2 db = p - t0.xy;
    if (rr <= 0.0 || dot(db, db) > rr * rr) continue;
    highp vec4 t1 = texelFetch(uGapData, ivec2(1, row), 0);
    highp vec4 t2 = texelFetch(uGapData, ivec2(2, row), 0);
    highp float hO = t2.z;
    highp float gst = gapStrength(t1.w);
    highp float inWin = 1.0;
    highp float inFoot = 1.0;
    // Arc distance to the nearer window end (fade ramp below).
    highp float winM = 1e6;
    // Signed arc offset along the under thread (fans: projected).
    highp float offA = 0.0;
    highp float fa = 0.0;
    highp vec4 t5 = vec4(0.0);
    highp vec4 t6 = vec4(0.0);
      // Arc offset from the window center along the under chain
      // (wrapped on closed rings), then the window test with a one-pixel
      // AA ramp at its ends.
      fa = turn * t1.x;
      highp float off = fa - t1.y;
      if (t1.z > 0.0) off -= t1.z * floor(off / t1.z + 0.5);
      offA = off;
      highp float m = min(off + t2.x, t2.y - off);
      if (m <= -pxW) continue;
      inWin = clamp(m / pxW + 0.5, 0.0, 1.0);
      winM = m;
    highp vec4 t3 = texelFetch(uGapData, ivec2(3, row), 0);
    int fl = int(t3.w + 0.5);
    bool perp = (fl & 1) != 0;
    int n = int(t2.w + 0.5);
    highp float kLast = float(max(n - 1, 0));
    int nCh = n >= 2 ? (n - 2) / 8 + 1 : 0;
    highp vec4 t4 = texelFetch(uGapData, ivec2(4, row), 0);
    highp vec4 t9 = texelFetch(uGapData, ivec2(9, row), 0);
    highp float ex = 0.0;
    highp float s0 = 0.0;
    highp float st = 0.0;
    highp float per = 0.0;
    if ((fl & 2) != 0 && !fan) {
      ex = t4.x;
      s0 = float(int(floor(t4.z + 0.5))) * t4.w;
      st = float(max(int(t9.x + 0.5), 1)) * t4.w;
      per = t1.z;
    }
    // REACH of interest (texel 0 holds it grown by the bounding radius):
    // beyond it nothing this slot does is visible. Inside SURE the
    // fragment is hidden whatever the margin, protect, fade or smooth-min
    // say (the silhouette always hides; the fan cut is inset one pixel
    // more), so the search may stop there.
    highp float reach = full ? hO + (t0.z - t0.w) + 2.0 * pxW : hO + pxW;
    // Zoom-aware tolerance (G3-1): the sure exit's inset floors at one
    // SAMP sample's arc. Not at the stride (K573 step 2): every d below
    // comes from the same strided walk, so a pixel of inset already keeps
    // the verdict, and a stride-3 inset left a thin thread no sure zone.
    highp float tol = max(pxW, t4.w);
    highp float sure = hO - ((full && !fan) ? 1.0 : 1.5) * tol;
    highp float sure2 = sure > 0.0 ? sure * sure : 0.0;
    highp float best = reach * reach;
    int bk = -1;
    if (n <= 1) {
      // The marker disc (n 0: texel 5's center) or a single sampled point.
      highp vec2 cpt = n == 0
        ? texelFetch(uGapData, ivec2(5, row), 0).zw
        : gapOverPt(t4, t9, 0);
      highp vec2 dq = p - cpt;
      best = dot(dq, dq);
      bk = 0;
      if (best >= reach * reach) continue;
    } else if (ex > 0.0) {
      gapNearestFull(row, nCh, p, ex, fa, s0, st, per, 1, 0,
        sure2, t4, t9, n, best, bk);
    } else {
      gapNearestFast(row, nCh, p, sure2, t4, t9, n, best, bk);
    }
    if (bk < 0) continue; // Nothing of this slot within reach.
    if (best < sure2) {
      keep = min(keep, 1.0 - (full ? inWin * inFoot : 1.0) * gst);
      continue;
    }
    // PROTECT: where this thread covers another one at a neighboring
    // crossing it keeps everything but the silhouette (see the header) -
    // inside the arc interval, over that thread's ribbon only. Evaluated
    // here, where few values are live; one inlined cover loop serves both
    // sides (the presence of the code, not its execution, is most of its
    // cost: register pressure).
    highp float pr = 0.0;
    if (!fan) {
      highp vec4 t7 = texelFetch(uGapData, ivec2(7, row), 0);
      highp float pn = gapInterval(offA, t7.x, t7.y);
      highp float pp = gapInterval(offA, t7.z, t7.w);
      for (int sd = 0; sd < 2; sd++) {
        highp float pi = sd == 0 ? pn : pp;
        if (pi <= 0.0) continue;
        pr = max(pr, pi * gapProtCover(row,
          18 + sd * 2, p, hO, pxW));
      }
      t5 = texelFetch(uGapData, ivec2(5, row), 0);
      t6 = texelFetch(uGapData, ivec2(6, row), 0);
    }
    highp vec4 t8 = texelFetch(uGapData, ivec2(8, row), 0);
    // Over tangent at the nearest point: central-difference tangents at
    // the nearest segment's ends, blended by the nearest parameter (a
    // per-segment direction steps at every vertex - visible as kinks in
    // the arc-length margin at tight over bends). Only the arc margin and
    // the fade read it.
    highp vec2 to = vec2(1.0, 0.0);
    bool needTan = full && (!perp || t8.y > 0.0);
    highp vec2 tu = t6.xy;
    if (n >= 2 && needTan) {
      if (!fan) {
        highp float tl = length(tanv);
        if (tl > 1e-3) tu = tanv / tl;
      }
      highp vec2 pm = gapOverPt(t4, t9, bk - 1);
      highp vec2 p0 = gapOverPt(t4, t9, bk);
      highp vec2 p1 = gapOverPt(t4, t9, bk + 1);
      highp vec2 pp = gapOverPt(t4, t9, bk + 2);
      // The nearest parameter on segment bk (zero-length: 0).
      highp vec2 abk = p1 - p0;
      highp float blk = dot(abk, abk);
      highp float bt = blk > 1e-12 ? clamp(dot(p - p0, abk) / blk, 0.0, 1.0) : 0.0;
      highp vec2 ta = p1 - pm;
      highp vec2 tb = pp - p0;
      ta /= max(length(ta), 1e-6);
      tb /= max(length(tb), 1e-6);
      to = mix(ta, tb, bt);
      to /= max(length(to), 1e-6);
    }
    highp float d = sqrt(best);
    // A one-point polyline (marker disc) has no direction: radial, sin 1.
    highp float sinT =
      n >= 2 && needTan ? abs(tu.x * to.y - tu.y * to.x) : 1.0;
    // Junction clearance, PER SIDE of the crossing (solved on the CPU from
    // the room a fused joint leaves, as the erase era capped its lanes):
    // margin and fade shrink only by the shortfall. The side switch at
    // offA = 0 lies inside the over silhouette, where everything hides.
    bool posSide = offA >= 0.0;
    highp float margin =
      (perp ? t8.x : t8.x * sinT) * (posSide ? t6.w : t6.z);
    // The FADE stays an arc length along the under thread in both looks
    // (fadeLength's meaning): perpendicular it is fade * sin - floored in
    // the casing look, where a parallel run has no along-thread exit.
    highp float fadeP =
      t8.y * (perp ? max(sinT, 0.2) : sinT) * (posSide ? t5.y : t5.x);
    margin *= 1.0 - pr;
    fadeP *= 1.0 - pr;
    highp float sk = t8.z;
    if (full && n >= 2 && sk > 0.0) {
      // FAR-BRANCH SMOOTH-MIN, edge band only: the blend can only lower d
      // by up to sminK / 4, so fragments already hidden or far outside are
      // settled without it.
      highp float lo = hO + margin - 0.5 * pxW;
      highp float hi = hO + margin + max(fadeP, pxW) + 0.25 * sk;
      if (d > lo && d < hi) {
        int farK = int(t8.w + 0.5);
        highp float best2 = (d + sk) * (d + sk);
        int bk2 = -1;
        gapNearestFull(row, nCh, p, ex, fa, s0, st, per,
          bk - farK, bk + farK, 0.0, t4, t9, n, best2, bk2);
        if (bk2 >= 0) {
          highp float d2 = sqrt(best2);
          highp float hb = clamp(0.5 + 0.5 * (d2 - d) / sk, 0.0, 1.0);
          d = mix(d2, d, hb) - sk * hb * (1.0 - hb);
        }
      }
    }
    highp float e = d - hO - margin;
    highp float k = clamp((e + 0.5 * pxW) / max(fadeP, pxW), 0.0, 1.0);
    k = k * k * (3.0 - 2.0 * k);
    // WINDOW-END FADE RAMP: where a window ends before the fade has run
    // out (twin midpoint split, neighbor clearance, the eye-wall limit),
    // the fade portion - never the casing - dissolves over the last half
    // fade of arc instead of being chopped by the window's straight end.
    highp float fs = clamp(winM / max(0.5 * t8.y, pxW), 0.0, 1.0);
    fs = mix(1.0, fs * fs * (3.0 - 2.0 * fs), clamp(e / pxW, 0.0, 1.0));
    highp float cut = full ? (1.0 - k) * inWin * inFoot * fs : 0.0;
    if (fan) {
      // The over silhouette, INSET one pixel so the AA ramp lands on the
      // over ribbon's opaque interior: a ramp centered on the silhouette
      // stacked on the ribbon's own MSAA edge let the backdrop through
      // (thin dark seams wherever a web met the over thread).
      cut = max(cut, 1.0 - clamp((d - hO + pxW) / pxW + 0.5, 0.0, 1.0));
    }
    keep = min(keep, 1.0 - cut * gst);
  }
  return keep;
}

// The fragment's arc turn - call in UNIFORM control flow (derivatives):
// the copy that does not jump across this triangle.
highp float gapTurn() {
  highp float fa = fwidth(vTurnA);
  highp float fb = fwidth(vTurnB);
  return fb < 0.5 * fa ? vTurnB : vTurnA;
}
highp float gapKeep(highp float pxW, highp float turn) {
  return gapKeepAt(pxW, vPos, turn, vTan, vMaskId);
}


float kJunctionCut(bool closed, float total, float arc, vec4 caps, float pxW) {
  float reach = uFabricGap.w;
  if (closed || reach <= 0.0) return 0.0;
  float d = 1e9;
  if (caps.z >= 4.0) d = min(d, arc);
  if (caps.w >= 4.0) d = min(d, total - arc);
  if (d >= reach) return 0.0;
  return clamp((reach - d) / max(pxW, 1e-5) + 0.5, 0.0, 1.0);
}
uniform highp sampler2D uRanges;
vec4 jRangeAt(int i) {
  return texelFetch(uRanges, ivec2(i & 1023, i >> 10), 0);
}
// K846: the same handover at EVERY junction arm, not only fused ends:
// within the fan reach of a junction, the ribbon's edge on a side a
// drawn wedge faces is interior (the through thread's far border
// crossing a spur's mouth; an arm's edge under its fillet flank), so
// only the wedge rim draws there. The chain's junction entries ride
// its RANGES segment space (samp_table RANGE_JUNCTION):
// (junction arc, signed arc window from it, side flags in chain
// terms) - WORLD arc throughout (K849: K846 packed spline-sample
// units, which the strip shader reads in ctrl units, so the cut
// almost never fired there). side is
// -1 on the chain's left edge, +1 on its right. An edge facing a
// skipped wedge (a near-straight pass) has no entry and keeps drawing.
float kJunctionSideCut(int chain, float arc, float total, bool closed, float side, float pxW) {
  float reach = uFabricGap.w;
  if (reach <= 0.0) return 0.0;
  vec4 ch1 = g3ChainAt(chain, 1);
  int n = int(ch1.w + 0.5);
  if (n <= 0) return 0.0;
  int base = int(ch1.z + 0.5);
  float cut = 0.0;
  for (int i = 0; i < 32; i++) {
    if (i >= n) break;
    vec4 e = jRangeAt(base + i);
    if (mod(e.w, 16.0) < 8.0) continue;
    bool cutSide = side < 0.0 ? mod(e.w, 32.0) >= 16.0 : e.w >= 32.0;
    if (!cutSide) continue;
    float rel = arc - e.x;
    if (closed) rel -= total * floor(rel / total + 0.5);
    if (rel < e.y || rel > e.z) continue;
    float d = abs(rel);
    float ext = max(abs(e.y), abs(e.z));
    cut = max(cut, clamp((ext - d) / max(pxW, 1e-5) + 0.5, 0.0, 1.0));
  }
  return cut;
}

void main(void) {
  highp vec2 gfw = fwidth(vPos);
  highp float pxW = max(max(gfw.x, gfw.y), 1e-5);
  highp float gTurn = gapTurn();
  // G2: this fragment's chain point (wrap-pair picks need derivatives in
  // uniform control flow - here, at the top), and its world arc per pixel
  // (the gameplay paint's edge coverage).
  KChain kc = kFragChain();
  highp vec2 kpt = kFragPoint(kc);
  highp vec2 ksw = fwidth(vSamp);
  highp float pxArc = (ksw.y < 0.5 * ksw.x ? ksw.y : ksw.x) * float(kc.count) * kc.arcPer;
  if (uKBase.z > 0.5 && uKBase.z < 4.5) {
    // DEBUG VIEW (probes): 1 = ctrl, 2 = arc - (fract(v), fract(16 v),
    // chain / 63); the census decodes 1e-4 precision through 8 bits.
    highp float kv = uKBase.z < 1.5 ? kCtrlNear(kc, kpt.x, kpt.y) : kpt.x;
    finalColor = vec4(fract(kv), fract(kv * 16.0), float(kc.ch % 64) / 63.0, 1.0);
    return;
  }
  vec3 base = vSection;
#ifdef K_ROOT
  // K620: a tapered root wears its strokes' sections, blending into its own at J.
  if (vKR0.x > 0.5 && kpt.x < vKR0.z) base = kRootSection(kpt.x, pxW);
#endif
  highp float pRain = 0.0;
  highp float aM = 1.0;
  // The exact ctrl, when the FX (kFxColor's own early outs hoisted: no
  // style, or this chain's FX all settled) or the paint / glow need it.
  bool fxHere = uKFx.w > 0.5 && uKFx.x > 0.5 && uKFx.z < kc.fxDone;
  bool paintHere = (uKPaint.x > 0.5 && kc.paintOn) || uKFx2.z > 0.5;
  highp float kctrl = fxHere || paintHere ? kCtrlNear(kc, kpt.x, kpt.y) : 0.0;
  if (fxHere) base = kFxColor(kc, kctrl, kpt.x / kc.arcPer, base, pRain, aM);
  if (pRain > 0.0) base = kRainbowBlend(base, pRain, vUV.y);
  // Gameplay paint + the reveal glow, composed over the section (G2.3).
  highp vec4 kst = paintHere ? kPaintAt(kc, kctrl, kpt.x, pxArc, false) : vec4(0.0);
  highp float kgl = paintHere ? kGlow(kc, kctrl) : 0.0;
  // K799: the traveled path's look (uKPath.x = width 0..1, .y = texture
  // 0 solid, 1 pencil, 2 crayon, 3 highlighter): narrow the gold toward
  // the centerline and grain it, ribbon-only (fans and strips keep the
  // full fill). A width of 0 hides the gold entirely.
  if (paintHere && kst.x > 0.0 && (uKPath.x < 1.0 || uKPath.y > 0.5)) {
    highp float ge = abs(2.0 * vUV.y - 1.0);
    // K835: fill wobble (uKPathB.x) + smooth excursion swell (uKPathB.y).
    if (uKPath.y > 0.5 && (uKPathB.x > 0.0 || uKPathB.y > 0.0)) ge += sin(vUV.x * 43.0 + sin(vUV.x * 17.0) * 1.7) * 0.22 * uKPathB.x + sin(vUV.x * 9.0 + sin(vUV.x * 23.0) * 0.7) * 0.45 * uKPathB.y;
    highp float fwG = max(fwidth(vUV.y) * 3.0, 0.02);
    highp float gw2 = uKPath.y > 2.5 ? min(uKPath.x * 1.15, 1.0) : uKPath.x;
    highp float gm = clamp((gw2 - ge) / fwG + 0.5, 0.0, 1.0)
      * step(0.001, uKPath.x);
    // K820: the grain's strength (uKHlPulse.w; 1 = the grain as drawn).
    if (uKPath.y > 0.5 && uKPath.y < 1.5) {
      gm *= mix(1.0, 0.7 + 0.3 * fract(sin(dot(
        floor(vec2(vUV.x * 260.0, ge * 7.0)),
        vec2(12.9898, 78.233))) * 43758.5453), uKHlPulse.w);
    } else if (uKPath.y > 1.5 && uKPath.y < 2.5) {
      gm *= mix(1.0, 0.45 + 0.55 * fract(sin(dot(
        floor(vec2(vUV.x * 90.0, ge * 4.0)),
        vec2(26.651, 41.313))) * 28001.8384), uKHlPulse.w);
    } else if (uKPath.y > 2.5) {
      gm *= mix(1.0, 0.55, uKHlPulse.w);
    }
    kst.x *= gm;
  }
  // K813: the pulse band's width across the thread (uKPath.z; 1 = the
  // whole thread, as the bands drew before it had a width).
  if (paintHere && kst.y > 0.5 && uKPath.z < 1.0) {
    highp float pe = abs(2.0 * vUV.y - 1.0);
    highp float pfw = max(fwidth(vUV.y) * 3.0, 0.02);
    kst.z *= clamp((uKPath.z - pe) / pfw + 0.5, 0.0, 1.0);
  }
  // The hover glow (K145): kst.w is its strength along the thread, shaped
  // across the ribbon here (only the ribbons have an across coordinate).
  highp float krim = kst.w > 0.0 ? kst.w * kRimAcross(vUV.y) : 0.0;
  // A High contrast prototype shapes a choice across the ribbon (K111
  // stage 4; kComposePaint itself under today's look).
  vec3 rgb = paintHere ? kComposePaintAcross(base, kst, kgl, vUV.y) : base;
  // K525: the telegraph rims (paint_glsl.ts TELE_ITEM_GLSL). K813: the
  // rims shape across by the telegraph's own width (kTeleAcross).
  if (kTele > 0.0) rgb = kTeleOver(rgb, kTele * kTeleAcross(vUV.y) * uKTele.w);
  // K298: the hover glow composes OVER the paint, so it shows on a hovered
  // choice at every breath phase of its own hover band (a max with the
  // band hid it under the breath). Off a band and the reveal glow this is
  // the old max(kgl, krim) whitening exactly.
  if (krim > 0.0) rgb = kRimOver(rgb, krim);
  // K137 fray (4.3's look, prototype): a cracked run goes pale (mix
  // toward its luminance) and thin (frayA below keeps only the middle
  // of the ribbon). Ribbon-only: the fans keep the full fill, as with
  // K799's traveled look.
  highp float frayA = 1.0;
  vec3 frayTint = vec3(0.0);
  if (paintHere && kFrayHere > 0.0) {
    highp float lumF = dot(rgb, vec3(0.299, 0.587, 0.114));
    // K813: the tint is the thread's pale shade, or frayColor's pick.
    frayTint = mix(vec3(lumF) * 0.85, uKHlFray.rgb, uKHlFray.w);
    rgb = mix(rgb, frayTint, 0.75 * kFrayHere);
    highp float eF = abs(2.0 * vUV.y - 1.0);
    highp float fwF = max(fwidth(vUV.y) * 3.0, 0.02);
    // K813: the kept middle share is frayWidth (0.45 as it drew before).
    frayA = mix(1.0, clamp((uKPath.w - eF) / fwF + 0.5, 0.0, 1.0), kFrayHere);
  }
  // K813: in the border look the thread's own fill is gone, but the
  // indications that draw IN the fill stay: the traveled path, the
  // pulse bands, the hover glow, the reveal glow, the telegraph, the
  // fray and the intro FX. Compose them over nothing (an empty base)
  // and measure how much of each covers this pixel; the border branch
  // below puts that in the interior and the strokes on the edges.
  highp float hiA = 0.0;
  vec3 hiRgb = vec3(0.0);
  if (uKLook.x > 0.5 && uKLook.x < 1.5) {
    if (paintHere) {
      hiRgb = kComposePaintAcross(vec3(0.0), kst, kgl, vUV.y);
      if (kTele > 0.0) hiRgb = kTeleOver(hiRgb, kTele * uKTele.w);
    }
    if (krim > 0.0) hiRgb = kRimOver(hiRgb, krim);
    if (kFrayHere > 0.0) hiRgb = mix(hiRgb, frayTint, 0.75 * kFrayHere);
    hiA = clamp(
      max(max(kst.x, kst.y > 0.5 ? kst.z : 0.0), max(krim, max(kgl, kTele * uKTele.w))),
      0.0, 1.0);
    if (kFrayHere > 0.0) hiA = max(hiA, kFrayHere);
    // The intro: while the FX run, the composed color (FX over the
    // section, the paint over that) IS the fill, at its solidity.
    if (fxHere) {
      hiRgb = rgb;
      hiA = max(hiA, aM);
    }
  }
  // K797b THREAD LOOK (prototype; the CPU mirror and parity tests wait
  // for Levi's pick, per the ledger's render-prototype rule): an edge
  // stroke in darkened section color along each side. Border-only also
  // clears the interior, so over/under and joins read from the strokes
  // and the backdrop shows between them. Junction fans still fill.
  highp float lookA = 1.0;
  // K798: a border-at-a-time intro (uKLook.y: 1 = fill follows each
  // strand, 2 = all fills last; uKLook.z: the intro is running) makes
  // even the fill look draw its borders first while it runs.
  bool edgesIntro = uKLook.y > 0.5 && uKLook.z > 0.5;
  if (uKLook.x > 0.5 || edgesIntro) {
    highp float eAcross = abs(2.0 * vUV.y - 1.0);
    highp float fwA = max(fwidth(vUV.y) * 3.0, 0.02);
    // K820: the stroke's width (uKLook.w; 0.38 = the 0.62 band) and
    // color (uKBorder; auto = the darkened-section stroke as drawn).
    highp float edge = smoothstep(1.0 - uKLook.w, 1.0 - uKLook.w + fwA, eAcross);
    vec3 stroke = mix(mix(rgb * 0.30, vec3(0.09, 0.085, 0.08), 0.5), uKBorder.rgb, uKBorder.w);
    if (uKLook.x > 0.5 && uKLook.x < 1.5) {
      // K813: strokes on the edges; inside, only the highlights above.
      rgb = mix(hiRgb, stroke, edge);
      lookA = max(edge, hiA * (1.0 - edge));
    }
    else {
      rgb = mix(rgb, stroke, edge * 0.9);
      if (edgesIntro) {
        highp float fillOn = uKLook.y < 1.5
          ? (uKFx.z >= kc.fxDone ? 1.0 : 0.0)
          : 0.0;
        lookA = mix(fillOn, 1.0, edge);
      }
    }
  }
  // K832: within a fused junction's fan reach the fan's wedge rim is
  // the border outline, so the ribbon's material hands over to it
  // (border look only; fabric_sdf kJunctionCut).
  if (uKLook.x > 0.5 && uKLook.x < 1.5) {
    lookA *= 1.0 - kJunctionCut(kc.closed, kc.total, kpt.x, g3ChainAt(kc.ch, 0), pxW);
    // K846: and at every junction arm, on the sides a wedge faces.
    lookA *= 1.0 - kJunctionSideCut(kc.ch, kpt.x, kc.total, kc.closed, vUV.y < 0.5 ? -1.0 : 1.0, pxW);
  }
  float gk = gapKeep(pxW, gTurn);
  if (uKBase.z > 4.5) {
    // DEBUG VIEW 5 (probes): the paint terms of the VISIBLE thread (gaps
    // cut as in the normal view) - (gold amount p, the pulse band's
    // strength v, the reveal glow or the hover rim, the stronger; the rim
    // composes over the paint since K298).
    if (gk <= 0.002) discard;
    finalColor = vec4(clamp(kst.x, 0.0, 1.0), kst.y > 0.5 ? kst.z : 0.0, max(kgl, krim), 1.0);
    return;
  }
  // Probe view (globals texel .y): masked material tinted, not removed
  // (only masked fragments read the flag).
  if (gk < 1.0 && gapProbe()) {
    rgb = mix(rgb, vec3(1.0, 0.0, 0.85), (1.0 - gk) * 0.75);
    gk = 1.0;
  }
  if (gk * lookA * frayA <= 0.002) discard;
  finalColor = vec4(rgb, 1.0) * vColor * (aM * gk * lookA * frayA);
}

