#version 300 es
#define SHADER_NAME pluck-blur-fragment
precision mediump float;

precision highp float;

in float vLat;
in float vCap;
in vec2 vEnv;
in vec4 vAux;
in vec3 vCol;
in vec2 vPos;
in vec4 vClipA;
in vec4 vClipB;
in vec4 vClipF;
in vec4 vColor;

out vec4 finalColor;

// (half-width h, partner casing band, ghost tint, sheen (K279))

uniform vec4 uKBase;
uniform vec4 uKFx;
uniform vec4 uKFx2;
uniform vec4 uKShape;
uniform vec4 uKInk;
uniform vec4 uKKnots[8];
uniform vec4 uKGamut;
uniform vec4 uKSect;
uniform vec4 uKPaint;
uniform vec4 uKPulse;
uniform vec4 uKReach;
uniform vec4 uKGold;
uniform vec4 uKLook;
uniform vec4 uKPath;
uniform vec4 uKPathB;
uniform vec4 uKHlPulse;
uniform vec4 uKHlHover;
uniform vec4 uKHlFray;
uniform vec4 uKBorder;

uniform vec4 uPluck;

const float PI = 3.141592653589793;
const float SHEEN_WHITE = 0.6;

// Integral of the arcsine CDF on [lo, hi]: 0 below, r at hi, slope 1
// beyond. Differencing it box-filters the dwell density over the pixel.
float G(float y, float lo, float hi) {
  float r = 0.5 * (hi - lo);
  float c = 0.5 * (hi + lo);
  if (r < 1e-6) return max(0.0, y - c);
  float t = (y - c) / r;
  if (t <= -1.0) return 0.0;
  if (t >= 1.0) return r * t;
  return r * (0.5 * t + (t * asin(t) + sqrt(max(0.0, 1.0 - t * t))) / PI);
}

// Time-averaged coverage of a thread of half-width h whose centerline
// dwells on [lo, hi] with the arcsine density, over a pixel of width p.
float cover(float u, float h, float lo, float hi, float p) {
  float a = G(u + h + 0.5 * p, lo, hi) - G(u + h - 0.5 * p, lo, hi);
  float b = G(u - h + 0.5 * p, lo, hi) - G(u - h - 0.5 * p, lo, hi);
  return clamp((a - b) / p, 0.0, 1.0);
}

float band(float v, float h, float p) {
  return clamp((h - abs(v)) / p + 0.5, 0.0, 1.0);
}

// K797b THREAD LOOK for a moving pluck: the solid thread becomes two
// edge bands, each offset 0.81h from the displaced centre and 0.19h in
// half-width (the ribbon stroke occupies e in [0.62, 1]). The attack
// snapshots and the strobe ghost take the same two-band form.
float strokeSpan(float u, float halfW, float lo, float hi, float m, float p) {
  float bh = max(halfW * 0.19, p * 0.5);
  float d = halfW * 0.81;
  float c = (1.0 - m) * (
    cover(u, bh, lo - d, hi - d, p) +
    cover(u, bh, lo + d, hi + d, p));
  c += 0.5 * m * (
    band(u - (hi - d), bh, p) + band(u - (lo - d), bh, p) +
    band(u - (hi + d), bh, p) + band(u - (lo + d), bh, p));
  return clamp(c, 0.0, 1.0);
}
float strokeGhost(float u, float center, float halfW, float p) {
  float bh = max(halfW * 0.19, p * 0.5);
  float d = halfW * 0.81;
  return clamp(
    band(u - (center - d), bh, p) + band(u - (center + d), bh, p),
    0.0, 1.0);
}

// Rule 4: inside the partner's casing band near an UNDER node -> hidden.
// The partner is a straight line through the crossing, trusted only out
// to reach along it (it curves away beyond), fading over the last 0.2.
float clipAt(vec4 L, float reach, vec2 P, float px) {
  if (reach <= 0.0) return 1.0;
  vec2 d = P - L.xy;
  float along = abs(dot(d, L.zw));
  if (along > reach) return 1.0;
  float perp = abs(d.x * L.w - d.y * L.z);
  float k = clamp((perp - uPluck.y) / px + 0.5, 0.0, 1.0);
  return mix(k, 1.0, smoothstep(reach - 0.2, reach, along));
}

// K344: a clip at weight w. On a self-crossing the under node's clip fades
// out before the arc reaches the chain's own over pass (pluck_model's
// underClipWeight; its CPU mirror is clipKeep); w = 1 is clipAt exactly.
float clipW(vec4 L, float reach, float w, vec2 P, float px) {
  float k = clipAt(L, reach, P, px);
  return w >= 1.0 ? k : mix(1.0, k, w);
}

void main(void) {
  // K459: over a free end's cap (vCap > 0) the thread narrows to the cap's
  // half-ellipse; vCap 0 is the full thread, exactly as before.
  float h = vCap > 0.0 ? uPluck.x * sqrt(max(0.0, 1.0 - vCap * vCap)) : uPluck.x;
  float p = max(length(vec2(dFdx(vLat), dFdy(vLat))), 1e-4);
  float lo = vEnv.x;
  float hi = vEnv.y;
  float m = vAux.x;
  bool lookBorder = uKLook.x > 0.5 && uKLook.x < 1.5;
  bool lookBoth = uKLook.x > 1.5;
  bool lookIntro = uKLook.y > 0.5 && uKLook.z > 0.5;
  bool edgeOnly = lookBorder || lookIntro;
  float cSolid = (1.0 - m) * cover(vLat, h, lo, hi, p)
    + 0.5 * m * (band(vLat - hi, h, p) + band(vLat - lo, h, p));
  float gSolid = vAux.z * band(vLat - vAux.y, h, p);
  float cEdge = edgeOnly || lookBoth
    ? strokeSpan(vLat, h, lo, hi, m, p) : 0.0;
  float gEdge = edgeOnly || lookBoth
    ? vAux.z * strokeGhost(vLat, vAux.y, h, p) : 0.0;
  float c = edgeOnly ? cEdge : cSolid;
  float g = edgeOnly ? gEdge : gSolid;
  vec3 gc = mix(vCol, vec3(1.0), uPluck.z);
  vec3 stroke = mix(mix(vCol * 0.30, vec3(0.09, 0.085, 0.08), 0.5), uKBorder.rgb, uKBorder.w);
  vec3 rgb = gc * g + (edgeOnly ? stroke : vCol) * c * (1.0 - g);
  float a = g + c * (1.0 - g);
  // K279 SHEEN: the swing's turning points (where a vibrating string dwells
  // longest) catch the light - a thin band at each edge of the swept
  // interval brightens toward white, fading in with the swing's width so a
  // pluck at rest draws the plain thread. 0 = the pre-K279 shader's output.
  if (uPluck.w > 0.0) {
    float sw = smoothstep(0.3 * h, 1.5 * h, hi - lo);
    float e = edgeOnly
      ? max(strokeGhost(vLat, hi, h, p), strokeGhost(vLat, lo, h, p))
      : max(band(vLat - hi, 0.55 * h, p), band(vLat - lo, 0.55 * h, p));
    rgb = mix(rgb, vec3(a), clamp(uPluck.w * sw * e * SHEEN_WHITE, 0.0, 1.0));
  }
  float px = max(length(dFdx(vPos)), 1e-4);
  float k = clipW(vClipA, vClipF.x, vClipF.z, vPos, px)
          * clipW(vClipB, vClipF.y, vClipF.w, vPos, px);
  if (lookBoth && !lookIntro) {
    float edgeMix = clamp(max(cEdge * (1.0 - g), gEdge), 0.0, 1.0) * 0.9;
    rgb = mix(rgb, stroke, edgeMix);
  }
  finalColor = vec4(rgb, a) * (vAux.w * k) * vColor;
}

