#version 300 es
#define SHADER_NAME section-rgb-explore-vertex
precision highp float;

precision highp float;
precision highp int;

in vec2 aPosition;
in vec2 aUV;

in vec2 aArcPos;
in vec2 aTan;
in vec4 aMaskId;
out highp vec2 vPos;
out highp float vTurnA;
out highp float vTurnB;
out highp vec2 vTan;
flat out highp vec4 vMaskId;


in vec2 aKey;
out highp vec2 vCtrl;
out highp vec2 vSamp;
flat out highp vec4 vKC0;
flat out highp vec4 vKC1;
flat out highp vec4 vKG0;
// K620: a tapered root's (1 + table texel, sideSign, arcJ, ctrlJ), its
// sides' sections at their feet, and the spur's section at J. K905: only
// in a root program (withRoot below).
#ifdef K_ROOT
flat out highp vec4 vKR0;
out vec3 vKRC;
out vec3 vKRO;
flat out vec3 vKRJ;
#endif
// The vertex's section color (PAINT_VERT_MAIN; needs PAINT_SECTION_GLSL).
vec3 kVertSection;

out vec2 vUV;
out vec3 vSection;
out vec4 vColor;

uniform mat3 uProjectionMatrix;
uniform mat3 uWorldTransformMatrix;
uniform vec4 uWorldColorAlpha;
uniform mat3 uTransformMatrix;
uniform vec4 uColor;

uniform vec4 uKBase;
uniform vec4 uKFx;
uniform vec4 uKFx2;
uniform vec4 uKShape;
uniform vec4 uKInk;
uniform vec4 uKKnots[8];
uniform vec4 uKGamut;
uniform vec4 uKSect;
uniform vec4 uKPaint;
uniform vec4 uKPulse;
uniform vec4 uKReach;
uniform vec4 uKGold;
uniform vec4 uKLook;
uniform vec4 uKPath;
uniform vec4 uKPathB;
uniform vec4 uKHlPulse;
uniform vec4 uKHlHover;
uniform vec4 uKHlFray;
uniform vec4 uKBorder;


const float REVEAL_TAPER_ARC = 0.3;
const float INK_TAPER_WORLD = 0.6;
const float REVEAL_CROSSING_MIN = 0.98;
const float REVEAL_GLOW_ARC = 1.15;
const float RAINBOW_GLOW_ARC = 2.4;
const float RAINBOW_GLOW_HOLD = 0.45;
const float BURN_EMBER_END = 0.4;
const float BURN_CHAR_END = 0.9;
const float BURN_RECOVER_END = 1.3;
const float BURN_HOT_ARC = 0.45;
const float ROOTS_START = 0.05;
const float ROOTS_FADE = 1.0;
const float RAINBOW_HOLD = 0.12;
const float RAINBOW_FADE = 0.65;
const float DUST_FADE_IN = 0.55;
const float COMET_FADE_IN = 1.0;
const float RAINBOW_SWELL = 1.0;
const float RAINBOW_SWELL_MIN_P = 0.2;
const float FAN_SOLID_START = 0.55;
const float FX_SOLID_EPS = 0.03;
const float CROSSING_FADE_IN = 0.36;
const float PULSE_FLOOR_REACH = 2.0;
const float CREST_WIDTH = 0.72;
const float PULSE_SPEED = 1.6;
const float PULSE_FLOOR = 0.38;
const float PULSE_CORE_BOOST = 0.62;
const float PULSE_CORE_RADIUS = 0.55;
const float CREST_RAMP = 0.5;
const float PULSE_END_WINDOW = 0.45;
const float PULSE_OUT_LEAD = 0.3;
const float PULSE_FADE_IN = 0.45;
const float HOVER_PULSE_W = 5.2;
const float PULSE_MIN_V = 0.004;
const float PULSE_REACH_FADE = 1.0;
const float RIM_END_SHARE = 0.6;
const float RIM_EDGE = 0.85;
const float K_BAND = 0.9315315315315315;
const float HC_LINE = 0.3;
const float HC_LINE_SOFT = 0.1;
const float HC_CORE = 0.65;
const float HC_CORE_SOFT = 0.15;
const float HC_CHEV_PERIOD = 0.8;
const float HC_CHEV_LEAN = 0.3;
const float RAMP_EASE_FULL = 1.0;
const int PI_SPAN = 1;
const int PI_CAP = 2;
const int PI_PULSE = 3;
const int PI_RIM = 4;
const int IF_INWARD = 1;
const int IF_HOVER = 4;
const int RF_GAMUT = 1;
const int RF_SWEEP = 2;
const int RF_NOISE = 4;
const int RF_RAMP_A = 8;
const int RF_RAMP_B = 16;
const float K_TAU = 6.283185307179586;
const float K_INV_TAU = 0.15915494309189535;


uniform highp sampler2D uKStatic;
uniform highp sampler2D uKGeom;
uniform highp sampler2D uKReveal;
uniform highp sampler2D uKPaintData;

highp vec4 kS(int i) { return texelFetch(uKStatic, ivec2(i & 1023, i >> 10), 0); }
highp vec4 kG(int i) { return texelFetch(uKGeom, ivec2(i & 1023, i >> 10), 0); }
highp vec4 kR(int i) { return texelFetch(uKReveal, ivec2(i & 1023, i >> 10), 0); }
highp vec4 kP(int i) { return texelFetch(uKPaintData, ivec2(i & 1023, i >> 10), 0); }

struct KChain {
  int ch;
  int nCtrl;
  bool closed;
  int count;
  int idx;
  int geom;
  int src0;
  int srcN;
  float total;
  float arcPer;
  float fxDone;
  bool paintOn;
};

KChain kChainOf(int ch, highp vec4 a, highp vec4 b, highp vec4 g) {
  KChain c;
  c.ch = ch;
  c.nCtrl = int(a.x + 0.5);
  c.closed = a.y > 0.5;
  c.count = int(a.z + 0.5);
  c.idx = int(a.w + 0.5);
  c.geom = int(b.x + 0.5);
  c.src0 = int(b.y + 0.5);
  c.srcN = int(b.z + 0.5);
  c.total = g.x;
  c.arcPer = g.y;
  c.fxDone = g.z;
  c.paintOn = g.w > 0.5;
  return c;
}

KChain kChain(int ch) {
  highp vec4 a = kS(2 * ch);
  highp vec4 b = kS(2 * ch + 1);
  return kChainOf(ch, a, b, kG(int(b.x + 0.5)));
}

// Control i's arc (i in [0, nCtrl)).
highp float kCA(KChain c, int i) {
  highp vec4 t = kG(c.geom + 1 + (i >> 2));
  int j = i & 3;
  return j == 0 ? t.x : j == 1 ? t.y : j == 2 ? t.z : t.w;
}

// K299: floor(fl / n) EXACTLY, for an integer-valued fl and n > 0 (a ring's
// lap). GPU float division is approximate (GLSL ES allows 2.5 ULP; ANGLE's
// D3D11 path multiplies by a reciprocal): on an RX 6800 XT floor(28.0 /
// 28.0) came out 0, and floor(k n / n) came out k - 1 for a fifth of (k, n).
// A lap one short put the slot index one past the chain's arc table, into
// the next chain's header: a closed chain's run ending at its seam drew its
// pulse and trail at a garbage arc. The quotient is within one of the
// truth, so one integer step corrects it.
int kLapOf(highp float fl, int n) {
  int k = int(floor(fl / float(n)));
  int r = int(fl) - k * n;
  return r < 0 ? k - 1 : r >= n ? k + 1 : k;
}

// x wrapped into [0, m) for m > 0, whatever the division's rounding (K299).
highp float kWrap(highp float x, highp float m) {
  highp float r = x - m * floor(x / m);
  if (r < 0.0) r += m;
  if (r >= m) r -= m;
  return r;
}

// A closed ring's arc of ctrl x within x's lap, in [0, total] (total only
// where the slot's fraction rounds to its end); the lap goes to kRingLap.
int kRingLap;
highp float kRingArc(KChain c, highp float x) {
  int n = c.nCtrl;
  highp float fl = floor(x);
  kRingLap = kLapOf(fl, n);
  int i0 = int(fl) - n * kRingLap;
  highp float a0 = kCA(c, i0);
  highp float a1 = i0 + 1 < n ? kCA(c, i0 + 1) : c.total;
  return a0 + (a1 - a0) * (x - fl);
}

// The renderer's paintArcAt: closed rings wrap, open chains clamp the slot
// (ctrl < 0 extrapolates to a negative arc, as on the CPU).
highp float kArcOfCtrl(KChain c, highp float x) {
  int n = c.nCtrl;
  if (c.closed) {
    highp float a = kRingArc(c, x);
    return a >= c.total ? a - c.total : a;
  }
  int i = clamp(int(floor(x)), 0, n - 1);
  highp float a0 = kCA(c, i);
  highp float a1 = i + 1 < n ? kCA(c, i + 1) : c.total;
  return min(c.total, a0 + (a1 - a0) * (x - float(i)));
}

// Monotone unwrapped arc of an unwrapped ctrl.
highp float kArcU(KChain c, highp float x) {
  if (!c.closed) return kArcOfCtrl(c, x);
  highp float a = kRingArc(c, x);
  return a + c.total * float(kRingLap);
}

// The bake's arc -> ctrl map, by binary search (vertex stage; 13 steps
// cover 8192 controls).
highp float kCtrlOfArc(KChain c, highp float a) {
  int lo = 0;
  int hi = c.nCtrl - 1;
  for (int it = 0; it < 14; it++) {
    if (lo >= hi) break;
    int m = (lo + hi + 1) >> 1;
    if (kCA(c, m) <= a) lo = m;
    else hi = m - 1;
  }
  highp float a0 = kCA(c, lo);
  highp float a1 = lo < c.nCtrl - 1 ? kCA(c, lo + 1) : c.total;
  return float(lo) + (a1 > a0 ? min(1.0, (a - a0) / (a1 - a0)) : 0.0);
}

// kCtrlOfArc's exact answer (the largest slot whose arc is <= a) by a short
// walk from a nearby ctrl; the binary search when the walk would be long.
highp float kCtrlOfArcNear(KChain c, highp float a, highp float seed) {
  int n = c.nCtrl;
  int s = clamp(int(floor(seed)), 0, n - 1);
  bool ok = false;
  for (int it = 0; it < 8; it++) {
    if (s < n - 1 && kCA(c, s + 1) <= a) { s++; continue; }
    if (s > 0 && kCA(c, s) > a) { s--; continue; }
    ok = true;
    break;
  }
  if (!ok) return kCtrlOfArc(c, a);
  highp float a0 = kCA(c, s);
  highp float a1 = s < n - 1 ? kCA(c, s + 1) : c.total;
  return float(s) + (a1 > a0 ? min(1.0, (a - a0) / (a1 - a0)) : 0.0);
}

// The exact ctrl at arc a from an approximate one (fragment stage: the
// interpolated vertex ctrl is off by a fraction of a slot where a control
// breakpoint falls inside a quad): ring-aware slot walk, then the clamped
// fraction.
highp float kCtrlNear(KChain c, highp float a, highp float approx) {
  int n = c.nCtrl;
  int s = int(floor(approx));
  if (c.closed) s -= n * kLapOf(float(s), n);
  else s = clamp(s, 0, n - 1);
  highp float a0 = 0.0;
  highp float a1 = 0.0;
  for (int it = 0; it < 6; it++) {
    a0 = kCA(c, s);
    a1 = s + 1 < n ? kCA(c, s + 1) : c.total;
    highp float d = a - a0;
    if (c.closed) d -= c.total * floor(d / c.total + 0.5);
    if (d < 0.0) {
      if (!c.closed && s == 0) break;
      s = s == 0 ? n - 1 : s - 1;
    } else if (d >= a1 - a0) {
      if (!c.closed && s == n - 1) break;
      s = s + 1 == n ? 0 : s + 1;
    } else {
      break;
    }
  }
  highp float d = a - a0;
  if (c.closed) d -= c.total * floor(d / c.total + 0.5);
  highp float t = a1 > a0 ? clamp(d / (a1 - a0), 0.0, 1.0) : 0.0;
  return float(s) + t;
}



vec3 kHsl(highp float h, highp float s, highp float l) {
  highp float a = s * min(l, 1.0 - l);
  highp vec3 x = vec3(0.0, 8.0, 4.0) + h / 30.0;
  highp vec3 k = x - 12.0 * floor(x / 12.0);
  return l - a * max(vec3(-1.0), min(k - 3.0, min(9.0 - k, vec3(1.0))));
}

vec3 kGamut(highp float v) {
  highp float x = uKGamut.x + (v - 0.5) * uKGamut.y;
  return kHsl(x - 360.0 * floor(x / 360.0), uKGamut.z, uKGamut.w);
}

highp float kEase(highp float u) {
  return u + (u * u * (3.0 - 2.0 * u) - u) * uKSect.y;
}

// A run's section color at ctrl, given its slot's CTRLIDX texel and the
// run's 4 texels (knotSection after the lookup; kSectionAtArc reuses one
// fetch for two nearby ctrls of the same run).
vec3 kRunSection(KChain c, highp float ctrl, int sl, highp vec4 I,
    highp vec4 R0, highp vec4 R1, highp vec4 R2, highp vec4 R3) {
  int n = c.nCtrl;
  int fl = int(R1.w + 0.5);
  if ((fl & RF_NOISE) != 0) {
    int j = c.closed ? (sl + 1 == n ? 0 : sl + 1) : min(sl + 1, n - 1);
    return kGamut(I.z + (kS(c.idx + j).z - I.z) * (ctrl - float(sl)));
  }
  highp float cu = c.closed && ctrl < R0.x - 1e-4 ? ctrl + float(n) : ctrl;
  if ((fl & RF_SWEEP) != 0) {
    highp float t = clamp((cu - R0.x) / max(R0.y - R0.x, 1e-6), 0.0, 1.0);
    highp float v = R1.x + (R3.x - R1.x) * t;
    return (fl & RF_GAMUT) != 0 ? kGamut(v) : vec3(v, 0.0, 0.0);
  }
  highp float sp = R0.y - R0.x;
  highp float extra = uKSect.x * R2.w;
  highp float ra = (fl & RF_RAMP_A) != 0 ? min(0.5 * sp, R0.z + extra) : 0.0;
  highp float rb = (fl & RF_RAMP_B) != 0 ? min(0.5 * sp, R0.w + extra) : 0.0;
  highp float da = cu - R0.x;
  highp float db = R0.y - cu;
  highp float w = 0.0;
  highp vec3 far = R3.xyz;
  if (ra > 0.0 && da < ra) {
    w = 1.0 - kEase(clamp(da / ra, 0.0, 1.0));
    far = R1.xyz;
  } else if (rb > 0.0 && db < rb) {
    w = 1.0 - kEase(clamp(db / rb, 0.0, 1.0));
  }
  highp vec3 col = R2.xyz + (far - R2.xyz) * w;
  return (fl & RF_GAMUT) != 0 ? kGamut(col.x) : col;
}

vec3 knotSection(KChain c, highp float ctrl) {
  int sl = clamp(int(floor(ctrl)), 0, c.nCtrl - 1);
  highp vec4 I = kS(c.idx + sl);
  int b = int(uKBase.x + 0.5) + 4 * int(I.x + 0.5);
  return kRunSection(c, ctrl, sl, I, kS(b), kS(b + 1), kS(b + 2), kS(b + 3));
}
// The RIBBON's section color at arc a: the section at the two bracketing
// samples' ctrls (what the vertex shader evaluates there), lerped - joinery
// must match the ribbons across their whole width (render lore). seed = a
// ctrl near a (< 0: none). kSecK0 returns the first sample's ctrl.
highp float kSecK0;
vec3 kSectionAtArc(KChain c, highp float a, highp float seed) {
  highp float total = c.total;
  int count = c.count;
  if (!(total > 0.0) || count < 2) {
    kSecK0 = 0.0;
    return knotSection(c, 0.0);
  }
  int k0;
  int k1;
  highp float fr;
  if (c.closed) {
    highp float an = kWrap(a, total);
    highp float f = an / total * float(count);
    highp float fl = floor(f);
    k0 = int(fl) % count;
    k1 = (k0 + 1) % count;
    fr = f - fl;
  } else {
    highp float an = clamp(a, 0.0, total);
    highp float f = an / total * float(count - 1);
    highp float fl = floor(f);
    k0 = min(int(fl), count - 1);
    k1 = min(count - 1, k0 + 1);
    fr = f - fl;
  }
  highp float A0 = float(k0) * c.arcPer;
  highp float c0 = seed >= 0.0 ? kCtrlOfArcNear(c, A0, seed) : kCtrlOfArc(c, A0);
  // The next sample's ctrl: in the same slot (the usual case) it is the
  // same closed form kCtrlOfArc ends with - no second walk.
  int q0 = clamp(int(floor(c0)), 0, c.nCtrl - 1);
  highp float qa0 = kCA(c, q0);
  highp float qa1 = q0 < c.nCtrl - 1 ? kCA(c, q0 + 1) : c.total;
  highp float A1 = float(k1) * c.arcPer;
  highp float c1 = k1 == 0
    ? kCtrlOfArc(c, 0.0)
    : A1 < qa1 && qa1 > qa0 && A1 >= qa0
      ? float(q0) + min(1.0, (A1 - qa0) / (qa1 - qa0))
      : kCtrlOfArcNear(c, A1, c0);
  kSecK0 = c0;
  // Both samples usually sit in one run: fetch it once.
  int n = c.nCtrl;
  int sl0 = clamp(int(floor(c0)), 0, n - 1);
  int sl1 = clamp(int(floor(c1)), 0, n - 1);
  highp vec4 I0 = kS(c.idx + sl0);
  highp vec4 I1 = sl1 == sl0 ? I0 : kS(c.idx + sl1);
  int b = int(uKBase.x + 0.5) + 4 * int(I0.x + 0.5);
  highp vec4 R0 = kS(b);
  highp vec4 R1 = kS(b + 1);
  highp vec4 R2 = kS(b + 2);
  highp vec4 R3 = kS(b + 3);
  vec3 s0 = kRunSection(c, c0, sl0, I0, R0, R1, R2, R3);
  vec3 s1 = int(I1.x + 0.5) == int(I0.x + 0.5)
    ? kRunSection(c, c1, sl1, I1, R0, R1, R2, R3)
    : knotSection(c, c1);
  return mix(s0, s1, fr);
}


void main(void) {
  mat3 mvp = uProjectionMatrix * uWorldTransformMatrix * uTransformMatrix;
  gl_Position = vec4((mvp * vec3(aPosition, 1.0)).xy, 0.0, 1.0);
  vUV = aUV;
  vColor = uColor * uWorldColorAlpha;

  vPos = aPosition;
  vTan = aTan;
  vMaskId = aMaskId;
  if (dot(aArcPos, aArcPos) < 0.25) {
    vTurnA = -1.0;
    vTurnB = -1.0;
  } else {
    highp float tn = atan(aArcPos.y, aArcPos.x) * 0.15915494309189535;
    if (tn < 0.0) tn += 1.0;
    vTurnA = tn;
    vTurnB = tn < 0.5 ? tn + 1.0 : tn;
  }


  {
    int kch = int(aKey.x + 0.5);
    highp vec4 kc0 = kS(2 * kch);
    highp vec4 kc1 = kS(2 * kch + 1);
    highp vec4 kg0 = kG(int(kc1.x + 0.5));
    KChain kc = kChainOf(kch, kc0, kc1, kg0);
    highp float kctrl = kCtrlOfArc(kc, aKey.y * kc.arcPer);
    highp float kcf = kctrl / float(kc.nCtrl);
    vCtrl = vec2(kcf, kc.closed && kcf < 0.5 ? kcf + 1.0 : kcf);
    highp float ksf = aKey.y / float(kc.count);
    vSamp = vec2(ksf, kc.closed && ksf < 0.5 ? ksf + 1.0 : ksf);
    vKC0 = kc0;
    vKC1 = vec4(kc1.xyz, float(kch));
    vKG0 = kg0;
    kVertSection = knotSection(kc, kctrl);
#ifdef K_ROOT
    // K620: a tapered root (C1.w = 1 + its table's KGEOM texel; paint_math
    // kRootVertSection, kRootSpurSection).
    vKR0 = vec4(0.0);
    vKRC = vec3(0.0);
    vKRO = vec3(0.0);
    vKRJ = vec3(0.0);
    if (kc1.w > 0.5) {
      int kt = int(kc1.w + 0.5) - 1;
      highp vec4 kh0 = kG(kt);
      highp vec4 kh1 = kG(kt + 1);
      if (kh1.x > 0.0) {
        highp float kf = clamp(aKey.y * kc.arcPer / kh1.x, 0.0, 1.0) * (kh0.z - 1.0);
        int ki = min(int(kh0.z + 0.5) - 2, int(floor(kf)));
        highp vec4 ke = mix(kG(kt + 2 + 2 * ki), kG(kt + 4 + 2 * ki), kf - float(ki));
        int kbc = int(kh0.x + 0.5);
        highp vec4 kb1 = kS(2 * kbc + 1);
        KChain kb = kChainOf(kbc, kS(2 * kbc), kb1, kG(int(kb1.x + 0.5)));
        vKR0 = vec4(kc1.w, kh0.y, kh1.xy);
        vKRC = kSectionAtArc(kb, ke.x, -1.0);
        vKRO = kSectionAtArc(kb, ke.y, -1.0);
        vKRJ = kSectionAtArc(kc, kh1.x, -1.0);
      }
    }
#endif
  }

  vSection = kVertSection;
}

