}
highp float exploreCutCover(int row, int fl, highp float A, highp float lat, highp float pxW) {
  kExCutOn = false;
  int look = int(uKExplore.y + 0.5);
  bool dots = look == 3 || look == 5;
  bool mx = (fl & 16) != 0;
  highp float best = mx ? -1.0 : 2.0;
  highp float bu = -1.0;
  highp float bs = 0.0;
  highp float bf = 0.0;
  for (int r = 0; r < 2; r++) {
    if ((fl & (1 << r)) == 0) continue;
    highp vec4 R = texelFetch(uGapData, ivec2(22 + r, row), 0);
    highp float d = (A - R.x) / R.y;
    highp float v = 1.0;
    highp float u = -1.0;
    if (d > 0.0) {
      highp float t = d < R.z
        ? d * (R.w / R.z)
        : R.w + (d - R.z) * ((1.0 - R.w) / max(1.0 - R.z, 1e-6));
      t = min(t, 1.0);
      v = 1.0 - t * t * (3.0 - 2.0 * t);
      if ((t < 1.0 || dots) && (fl & (4 << r)) != 0) u = t;
    }
    if (mx ? (v > best || (v == best && u < 0.0)) : v < best) {
      best = v;
      bu = u;
      bs = abs(A - R.x);
      bf = abs(R.y);
    }
  }
  if (best > 1.0) return 1.0;
  if (best < 0.0) return 0.0;
