  highp vec2 ksw = fwidth(vSamp);
  highp float pxArc = (ksw.y < 0.5 * ksw.x ? ksw.y : ksw.x) * float(kc.count) * kc.arcPer;
  highp float kSideFw = fwidth(vUV.y);
