#version 300 es
#define SHADER_NAME junction-field-explore-fragment
precision mediump float;


precision highp float;
precision highp int;
precision highp sampler2D;

uniform sampler2D uJData;
uniform vec4 uJParams;
uniform vec4 uJParams2;

uniform vec4 uKBase;
uniform vec4 uKFx;
uniform vec4 uKFx2;
uniform vec4 uKShape;
uniform vec4 uKInk;
uniform vec4 uKKnots[8];
uniform vec4 uKGamut;
uniform vec4 uKSect;
uniform vec4 uKPaint;
uniform vec4 uKPulse;
uniform vec4 uKReach;
uniform vec4 uKGold;
uniform vec4 uKLook;
uniform vec4 uKPath;
uniform vec4 uKPathB;
uniform vec4 uKHlPulse;
uniform vec4 uKHlHover;
uniform vec4 uKHlFray;
uniform vec4 uKBorder;


const float REVEAL_TAPER_ARC = 0.3;
const float INK_TAPER_WORLD = 0.6;
const float REVEAL_CROSSING_MIN = 0.98;
const float REVEAL_GLOW_ARC = 1.15;
const float RAINBOW_GLOW_ARC = 2.4;
const float RAINBOW_GLOW_HOLD = 0.45;
const float BURN_EMBER_END = 0.4;
const float BURN_CHAR_END = 0.9;
const float BURN_RECOVER_END = 1.3;
const float BURN_HOT_ARC = 0.45;
const float ROOTS_START = 0.05;
const float ROOTS_FADE = 1.0;
const float RAINBOW_HOLD = 0.12;
const float RAINBOW_FADE = 0.65;
const float DUST_FADE_IN = 0.55;
const float COMET_FADE_IN = 1.0;
const float RAINBOW_SWELL = 1.0;
const float RAINBOW_SWELL_MIN_P = 0.2;
const float FAN_SOLID_START = 0.55;
const float FX_SOLID_EPS = 0.03;
const float CROSSING_FADE_IN = 0.36;
const float PULSE_FLOOR_REACH = 2.0;
const float CREST_WIDTH = 0.72;
const float PULSE_SPEED = 1.6;
const float PULSE_FLOOR = 0.38;
const float PULSE_CORE_BOOST = 0.62;
const float PULSE_CORE_RADIUS = 0.55;
const float CREST_RAMP = 0.5;
const float PULSE_END_WINDOW = 0.45;
const float PULSE_OUT_LEAD = 0.3;
const float PULSE_FADE_IN = 0.45;
const float HOVER_PULSE_W = 5.2;
const float PULSE_MIN_V = 0.004;
const float PULSE_REACH_FADE = 1.0;
const float RIM_END_SHARE = 0.6;
const float RIM_EDGE = 0.85;
const float K_BAND = 0.9315315315315315;
const float HC_LINE = 0.3;
const float HC_LINE_SOFT = 0.1;
const float HC_CORE = 0.65;
const float HC_CORE_SOFT = 0.15;
const float HC_CHEV_PERIOD = 0.8;
const float HC_CHEV_LEAN = 0.3;
const float RAMP_EASE_FULL = 1.0;
const int PI_SPAN = 1;
const int PI_CAP = 2;
const int PI_PULSE = 3;
const int PI_RIM = 4;
const int IF_INWARD = 1;
const int IF_HOVER = 4;
const int RF_GAMUT = 1;
const int RF_SWEEP = 2;
const int RF_NOISE = 4;
const int RF_RAMP_A = 8;
const int RF_RAMP_B = 16;
const float K_TAU = 6.283185307179586;
const float K_INV_TAU = 0.15915494309189535;


highp float kSmooth(highp float x) {
  highp float c = clamp(x, 0.0, 1.0);
  return c * c * (3.0 - 2.0 * c);
}

highp float kRainbowP(highp float age) {
  return age >= RAINBOW_HOLD + RAINBOW_FADE
    ? 0.0
    : 1.0 - kSmooth((age - RAINBOW_HOLD) / RAINBOW_FADE);
}

highp float kMaterialize(highp float age, int style) {
  highp float e = style == 3 ? DUST_FADE_IN : COMET_FADE_IN;
  return age >= e ? 1.0 : kSmooth(age / e);
}


highp float kFxWeight(int style, highp float age) {
  if (style == 1) return kRainbowP(age);
  if (style == 2 || style == 3) return kMaterialize(age, style) - 1.0;
  return 0.0;
}

highp float kFxSolid(highp float w) {
  if (w < 0.0) return 1.0 + w;
  if (w > 0.0) return 1.0 - kSmooth((w - 0.06) / 0.34);
  return 1.0;
}

highp float kFanAlpha(highp float solid) {
  highp float a = kSmooth((solid - FAN_SOLID_START) / (1.0 - FAN_SOLID_START));
  return a >= 0.999 ? 1.0 : a;
}

// The joint gate (record header J1 = (tOn, tLast)).
highp float knotFanAlpha(highp vec4 J1) {
  if (uKFx.w < 0.5) return 1.0;
  if (uKFx.z < J1.x) return 0.0;
  return kFanAlpha(kFxSolid(kFxWeight(int(uKFx.x + 0.5), uKFx.z - J1.y)));
}


uniform highp sampler2D uStrip;
vec3 stripAt(int row, highp float x) {
  highp float xc = clamp(x, 0.0, 63.0);
  int k0 = int(floor(xc));
  int k1 = min(k0 + 1, 63);
  highp float f = xc - float(k0);
  ivec2 base = ivec2((row & 15) << 6, row >> 4);
  vec3 a = texelFetch(uStrip, base + ivec2(k0, 0), 0).rgb;
  vec3 b = texelFetch(uStrip, base + ivec2(k1, 0), 0).rgb;
  return mix(a, b, f);
}


// The pulse trains' reach window (K75): full strength out to reach - fade
// from the junction, smoothly gone at reach. The hover stops there too
// (K93).
highp float kReachWin(highp float d) {
  highp float f = max(uKReach.y, 1e-4);
  return 1.0 - kSmooth((d - (uKReach.x - f)) / f);
}
// K111 stage 4 (K265): High contrast's highlight prototype, uKBase.y. 0 =
// today's pulses: every prototype branch is skipped and the paint is
// master's. 1 contrast, 2 outline, 3 chevrons (kComposePaintAcross). The
// CPU mirror draws the pulses whatever the id (prototypes skip parity,
// K152 (3); the picked look gets its mirror in stage 5).
int kHcLook() {
  return int(uKBase.y + 0.5);
}

// Brightness at global distance dG; bumpK scales the crest trains (1 on
// the arms and the fan's bands, 0 in a strip's quiet row). A High
// contrast prototype has no trains and no breath: one steady level out
// to the reach (the looks shape it; prototypes skip mirror parity).
highp float kPulseCrestK(highp float dG, bool inward, bool hovered, highp float endWin, highp float bumpK) {
  if (kHcLook() != 0) return endWin * uKPulse.w * kReachWin(dG);
  if (hovered) return endWin * uKPaint.w * kReachWin(dG);
  highp float s = uKPulse.z;
  highp float raw = inward ? dG + uKPulse.x : dG - uKPulse.y;
  highp float ph = raw - s * floor(raw / s);
  highp float dist = min(ph, s - ph);
  highp float dC = max(0.0, dG - (ph <= s - ph ? ph : ph - s));
  highp float bump = max(0.0, 1.0 - dist / CREST_WIDTH) * min(1.0, dC / CREST_RAMP) * bumpK;
  highp float fl = (PULSE_FLOOR + PULSE_CORE_BOOST * max(0.0, 1.0 - dG / PULSE_CORE_RADIUS)) *
    max(0.0, 1.0 - dG / PULSE_FLOOR_REACH);
  return min(1.0, (fl + bump * 0.9) * endWin) * uKPulse.w * kReachWin(dG);
}
highp float kPulseCrest(highp float dG, bool inward, bool hovered, highp float endWin) {
  return kPulseCrestK(dG, inward, hovered, endWin, 1.0);
}
highp float kPulseCrestQuiet(highp float dG, bool inward, bool hovered, highp float endWin) {
  return kPulseCrestK(dG, inward, hovered, endWin, 0.0);
}


// K1139 S3b: the pulse field this fan draws (Stage 2: the max over
// bands of crest x cover at this pixel), read back by debug view 5 in
// JUNCTION_FRAG.
// junctionField sets it; a pixel under no band keeps 0.
float kFanPulseV = 0.0;

const float TAU = 6.283185307179586;
const float HALF_PI = 1.5707963267948966;


vec4 stripAtP(int row, highp float x) {
  highp float xc = clamp(x, 0.0, 63.0);
  int k0 = int(floor(xc));
  int k1 = min(k0 + 1, 63);
  highp float f = xc - float(k0);
  ivec2 base = ivec2((row & 15) << 6, row >> 4);
  vec4 a = texelFetch(uStrip, base + ivec2(k0, 0), 0);
  vec4 b = texelFetch(uStrip, base + ivec2(k1, 0), 0);
  return mix(a, b, f);
}
vec4 jAt(int i) { return texelFetch(uJData, ivec2(i & 1023, i >> 10), 0); }

// An arm's COMPOSED material at arc offset s along it (clamped to its
// domain): its strip row (h.z) at s times the row's texels per world arc
// (h.w) - arm_strip.ts renders the material there once per frame. K81:
// untrav reads the arm's UNTRAVELED row (h.z + 1, routed records only);
// band floors the lookup at texel 1 (a gold span ending at the joint
// half-covers texel 0, and a band must not half-light its own start).
vec4 armPaint(int ab, float s, bool band, bool untrav) {
  vec4 h = jAt(ab);
  float sc = min(band ? max(s, 1.0 / h.w) : s, jAt(ab + 1).z);
  return stripAtP(int(h.z + 0.5) + (untrav ? 1 : 0), sc * h.w);
}
// Arc along an arm at projected radius rp (its radial profile; straight
// extrapolation past the grid).
float profArc(int ab, float rp) {
  int last = int(uJParams.y + 0.5) - 1;
  float x = rp / uJParams2.x;
  if (x >= float(last)) {
    return jAt(ab + 2 + last).y + (rp - float(last) * uJParams2.x);
  }
  int i = int(x);
  vec4 t = jAt(ab + 2 + i);
  return mix(t.y, t.w, x - float(i));
}


// The composed junction-field color at world point p for the record at
// texel rec: bracketing arms by their profile angles AT p's radius, each
// sampled at p's projected radius, EDGE-AWARE smoothstep blend across the
// gap between the two ribbons' edges. Each arm's material is COMPOSED
// (section RGB mixed with the accent at its own paint U, exactly as the
// section shader composes the ribbon) BEFORE the blend: lerping the raw U
// between arms swept the accent strip across unrelated paint families
// (band A -> base -> gold -> band B: phantom gold between two near-white
// pulse cores; a traveled/untraveled pair stepped sharply inside the
// blend instead of ramping) - the palette-order lore, field edition.
// untrav (K81, a routed record): every arm's UNTRAVELED row - the route
// bands put the gold back along the path itself.
vec4 junctionBase(int rec, vec2 p, vec4 hd, bool untrav) {
  int n = int(hd.z + 0.5);
  vec2 e = p - hd.xy;
  if (n == 0) {
    // AXIS record: (chain, strip row, texels per world, offset), then
    // (arc0, axis x, axis y, ctrl0) - the point's axis projection.
    vec4 hx = jAt(rec + 2);
    vec4 ax = jAt(rec + 3);
    return stripAtP(int(hx.y + 0.5), (dot(e, ax.yz) + hx.w) * hx.z);
  }
  float rho = length(e);
  float phi = atan(e.y, e.x);
  int profN = int(uJParams.y + 0.5);
  int last = profN - 1;
  int stride = 2 + profN;
  float gx = rho / uJParams2.x;
  int gi;
  float gf;
  if (gx >= float(last)) {
    gi = last - 1;
    gf = 1.0;
  } else {
    gi = int(gx);
    gf = gx - float(gi);
  }
  float relA = 1e9;
  float relB = 1e9;
  int ia = 0;
  int ib = 0;
  for (int i = 0; i < 12; i++) {
    if (i >= n) break;
    vec4 t = jAt(rec + 2 + i * stride + 2 + gi);
    float ra = phi - mix(t.x, t.z, gf);
    ra -= TAU * floor(ra / TAU);
    float rb = ra > 0.0 ? TAU - ra : 0.0;
    if (ra < relA) { relA = ra; ia = i; }
    if (rb < relB) { relB = rb; ib = i; }
  }
  int abA = rec + 2 + ia * stride;
  int abB = rec + 2 + ib * stride;
  // Probe views (uKBase.z 3 / 4): one bracketing arm's material alone.
  bool onlyA = ia == ib || (uKBase.z > 2.5 && uKBase.z < 3.5);
  bool onlyB = !onlyA && uKBase.z > 3.5 && uKBase.z < 4.5;
  // The blend weight does not depend on the materials: compute it first,
  // so a pixel inside one arm's footprint (t 0 or 1 - most of a web)
  // evaluates that arm alone (identical result: mix at 0 / 1 is exact).
  float t = 0.0;
  if (!onlyA && !onlyB) {
    float fh = uJParams.x;
    float span = relA + relB;
    float hw = rho > fh ? asin(fh / rho) : HALF_PI;
    float lo = hw;
    float hi = span - hw;
    float minW = span * uJParams2.y;
    if (hi - lo < minW) {
      lo = (span - minW) * 0.5;
      hi = lo + minW;
    }
    t = hi > lo ? (relA - lo) / (hi - lo) : (relA < span * 0.5 ? 0.0 : 1.0);
    t = clamp(t, 0.0, 1.0);
    t = t * t * (3.0 - 2.0 * t);
    if (t <= 0.0) onlyA = true;
    else if (t >= 1.0) onlyB = true;
  }
  vec4 cA = vec4(0.0);
  vec4 cB = vec4(0.0);
  if (!onlyB) {
    cA = armPaint(abA, profArc(abA, relA < HALF_PI ? rho * cos(relA) : 0.0), false, untrav);
    if (onlyA) return cA;
  }
  cB = armPaint(abB, profArc(abB, relB < HALF_PI ? rho * cos(relB) : 0.0), false, untrav);
  if (onlyB) return cB;
  return mix(cA, cB, t);
}

// The junction pass's color at p (pxW: world units per pixel; strip: the
// fragment belongs to a cover strip): the base field (a routed record's
// untraveled rows, unless J1.z marks it fully traveled - K127: then the
// composed rows, as before K81; K169: J1.z in (0, 1) is a web fading in, the
// two bases blended by it), then each K81 route band through this
// junction composed over it, oldest first (a revisit's newer pass wins
// where two cross). A band pixel takes its nearest point on the band's
// centerline polyline (and that point's tau). In a web the band edge is a
// one-pixel ramp CENTERED on the thread half-width, like a ribbon's MSAA
// edge, so the band is the thread's width. On a cover strip the band stays
// solid ROUTE_BAND_PAD pixels past the half-width before its ramp: the
// strip's own edge is the ribbon's MSAA edge (4x samples sit within 0.4 px
// of the pixel center, where this runs), and the pad keeps the untraveled
// material out of it. The probe views (uKBase.z 3 / 4) show the base alone.
vec4 junctionField(int rec, vec2 p, float pxW, vec4 j1, bool strip) {
  vec4 hd = jAt(rec);
  int nr = int(j1.w + 0.5);
  bool routed = nr > 0 && hd.z > 0.5;
  float fz = routed ? j1.z : 0.0;
  int base0 = int(hd.w + 0.5);
  // K1139 S3b: the pulse section (a count texel, then one block per
  // pulse band) sits right after the gold blocks. Walk to its count
  // before anything draws: a pulse-banded record's base reads its arms'
  // QUIET rows (no crest bars under the bands it draws). A record with
  // no blocks keeps base0 0.
  int np = 0;
  int pbase = base0;
  if (base0 > 0) {
    for (int r = 0; r < 4; r++) {
      if (r >= nr) break;
      pbase += 1 + int(jAt(pbase).x + 0.5);
    }
    np = int(jAt(pbase).x + 0.5);
  }
  bool banded = np > 0;
  vec4 c = junctionBase(rec, p, hd, (routed || banded) && fz < 0.5);
  if (routed && fz > 0.0 && fz < 1.0) {
    // K169: a web fading in blends its two bases (c is the side below 0.5).
    vec4 o = junctionBase(rec, p, hd, fz >= 0.5);
    c = fz < 0.5 ? mix(c, o, fz) : mix(o, c, fz);
  }
  if ((!routed && !banded) || (uKBase.z > 2.5 && uKBase.z < 4.5)) return c;
  int base = base0;
  int stride = 2 + int(uJParams.y + 0.5);
  float reach = uJParams.x + (strip ? 1.500 : 0.5) * pxW;
  for (int r = 0; r < 4; r++) {
    if (r >= nr) break;
    vec4 r0 = jAt(base);
    int nv = int(r0.x + 0.5);
    float best = 1e20;
    float tau = 0.0;
    float shift = 0.0;
    vec4 q0 = jAt(base + 1);
    for (int k = 0; k < 63; k++) {
      if (k + 1 >= nv) break;
      vec4 q1 = jAt(base + 2 + k);
      vec2 d = q1.xy - q0.xy;
      vec2 w = p - q0.xy;
      float l2 = dot(d, d);
      float u = l2 > 1e-12 ? clamp(dot(w, d) / l2, 0.0, 1.0) : 0.0;
      vec2 off = w - d * u;
      float dd = dot(off, off);
      if (dd < best) {
        best = dd;
        tau = mix(q0.z, q1.z, u);
        shift = mix(q0.w, q1.w, u);
      }
      q0 = q1;
    }
    float cov = clamp((reach - sqrt(best)) / pxW, 0.0, 1.0);
    if (cov > 0.0) {
      // A banded record's verts carry the strip-arc shift (their tau is
      // arc-true, K1139 S3b): the arms are sampled where the ribbon has
      // their material. Unbanded records write shift 0.
      vec4 bm = armPaint(rec + 2 + int(r0.z + 0.5) * stride, -tau + shift, true, false);
      if (r0.w > -0.5) {
        bm = mix(
          bm,
          armPaint(rec + 2 + int(r0.w + 0.5) * stride, tau + shift, true, false),
          smoothstep(-r0.y, r0.y, tau)
        );
      }
      c = mix(c, bm, cov);
    }
    base += 1 + nv;
  }
  // K1139 S3b: the pulse bands. Each block is R0 = (nVerts, m, armA,
  // armB), R1 = (distJ, flags, shared, code) - flags = inward + 2 *
  // hovered, shared = its pair already has a gold block above, code =
  // kA + 64 kB + 4096 mode (pulsePivot) - R2 = the pivot P homogeneous
  // (X, Y, w, gR) and R3 = the side line (a, b, c, 0), both relative to
  // the first vert, then its arc-true centerline verts (x, y, tau,
  // strip-arc shift). Stage 2 (a): with mode 1 a band's tau and shift
  // are the centreline's where the ray from P through the pixel meets it
  // (kA..kB), beyond the end rays the nearer L-end's projected along its
  // segment: continuous wherever the cover is above 0. Mode 0 keeps the
  // nearest foot. The cover stays the true distance's. The
  // crest is the arms' own field at dG = distJ + tau (PULSE_CREST_GLSL;
  // S4b: kPulseBandV), whitened over the arms' QUIET material: the quiet rows already wear
  // the crest's floor, so only the trains' share whitens here and the
  // band meets its arms. Stage 2 (b): no winner. kFanPulseV (debug 5)
  // is the max over every band of crest x cover; each drawing band
  // mixes its material in by its own weight, in block order, and the
  // whitening, the max over drawing bands of f x weight, is applied
  // once. (c): a drawing band's weight is its cover times its yield to
  // the shared bands' gold, a ramp over the 3 px where a shared band is
  // nearer (1 on a tie, S3b's tie rule). A shared band draws nothing:
  // its gold block carries the crest through the strips. (d): the crotch
  // between two drawing bands that share an arm, on the outer side of
  // both (their signed distances' signs differ, after the shared arm's
  // direction), takes the smaller of the two whitenings, each at its own
  // tau without the cover, ramped in by the sides' product and out by
  // the gap between the bands.
  int pb = pbase + 1;
  float dShared = 1e20;
  float sTau[4];
  float sShift[4];
  float sCov[4];
  float sDist[4];
  float sSd[4];
  float sF[4];
  int sPb[4];
  for (int r = 0; r < 4; r++) {
    if (r >= np) break;
    vec4 r0 = jAt(pb);
    vec4 r1 = jAt(pb + 1);
    vec4 r2 = jAt(pb + 2);
    vec4 r3 = jAt(pb + 3);
    int nv = int(r0.x + 0.5);
    int ic = int(r1.w + 0.5);
    int kA = ic - (ic / 64) * 64;
    int kB = ic / 64 - (ic / 4096) * 64;
    bool piv = ic >= 4096;
    float best = 1e20;
    float tau = 0.0;
    float shift = 0.0;
    vec4 v0 = jAt(pb + 4);
    vec2 pr = p - v0.xy;
    vec2 a0 = vec2(0.0);
    // s = w cross(v - v0, pr) + cross(XY, v - v0 - pr) = w cross(v - P,
    // p - P): which side of the ray from P a vertex lies on.
    float s0 = r2.y * pr.x - r2.x * pr.y;
    bool hit = false;
    float tauP = 0.0;
    float shiftP = 0.0;
    vec4 eA0 = v0;
    vec4 eA1 = v0;
    vec4 eB0 = v0;
    vec4 eB1 = v0;
    vec4 q0 = v0;
    float side = 0.0;
    for (int k = 0; k < 63; k++) {
      if (k + 1 >= nv) break;
      vec4 q1 = jAt(pb + 5 + k);
      vec2 d = q1.xy - q0.xy;
      vec2 w = p - q0.xy;
      float l2 = dot(d, d);
      float u = l2 > 1e-12 ? clamp(dot(w, d) / l2, 0.0, 1.0) : 0.0;
      vec2 off = w - d * u;
      float dd = dot(off, off);
      if (dd < best) {
        best = dd;
        tau = mix(q0.z, q1.z, u);
        shift = mix(q0.w, q1.w, u);
        side = d.x * w.y - d.y * w.x;
      }
      vec2 a1 = q1.xy - v0.xy;
      vec2 e1 = a1 - pr;
      float s1 = r2.z * (a1.x * pr.y - a1.y * pr.x) + (r2.x * e1.y - r2.y * e1.x);
      if (k == kA) {
        eA0 = q0;
        eA1 = q1;
      }
      if (k + 1 == kB) {
        eB0 = q0;
        eB1 = q1;
      }
      if (piv && !hit && k >= kA && k < kB && s0 != s1 &&
          ((s0 <= 0.0 && s1 >= 0.0) || (s0 >= 0.0 && s1 <= 0.0))) {
        float us = s0 / (s0 - s1);
        vec2 qh = mix(a0, a1, us);
        if (dot(r2.z * qh - r2.xy, r2.z * pr - r2.xy) > 0.0) {
          hit = true;
          tauP = mix(q0.z, q1.z, us);
          shiftP = mix(q0.w, q1.w, us);
        }
      }
      q0 = q1;
      a0 = a1;
      s0 = s1;
    }
    if (piv) {
      if (hit) {
        tau = tauP;
        shift = shiftP;
      } else if (dot(r3.xy, pr) + r3.z < 0.0) {
        tau = eA0.z + dot(p - eA0.xy, normalize(eA1.xy - eA0.xy));
        shift = eA0.w;
      } else {
        tau = eB1.z + dot(p - eB1.xy, normalize(eB1.xy - eB0.xy));
        shift = eB1.w;
      }
    }
    float dnow = sqrt(best);
    float cov = clamp((reach - dnow) / pxW, 0.0, 1.0);
    bool inw = r1.y == 1.0 || r1.y == 3.0;
    bool hov = r1.y > 1.5;
    float g = r1.x + tau;
    float bk = 1.0;
    if (tau > 0.0 && r2.w != 0.0) {
      float gR = abs(r2.w);
      bk = min(1.0, abs(g - gR) * 2.0000);
      if (g > gR) {
        g = 2.0 * gR - g;
        inw = r2.w < 0.0;
      }
    }
    float cr = kPulseCrestK(g, inw, hov, 1.0, bk);
    kFanPulseV = max(kFanPulseV, cr * cov);
    float fa = K_BAND * kPulseCrestQuiet(g, inw, hov, 1.0);
    if (r1.z >= 0.5) dShared = min(dShared, dnow);
    sTau[r] = tau;
    sShift[r] = shift;
    sCov[r] = r1.z < 0.5 ? cov : 0.0;
    sDist[r] = dnow;
    sSd[r] = side < 0.0 ? -dnow : dnow;
    sF[r] = r1.z < 0.5 ? clamp((K_BAND * cr - fa) / max(1.0 - fa, 1e-3), 0.0, 1.0) : 0.0;
    sPb[r] = pb;
    pb += 4 + nv;
  }
  float wW = 0.0;
  for (int r = 0; r < 4; r++) {
    if (r >= np) break;
    float yr = 1.0 - smoothstep(0.0, 3.0 * pxW, sDist[r] - dShared);
    float cw = sCov[r] * yr;
    vec4 r0 = jAt(sPb[r]);
    if (cw > 0.0) {
      float tau = sTau[r];
      vec4 pm = armPaint(rec + 2 + int(r0.z + 0.5) * stride, -tau + sShift[r], true, true);
      pm = mix(pm, armPaint(rec + 2 + int(r0.w + 0.5) * stride, tau + sShift[r], true, true), smoothstep(-r0.y, r0.y, tau));
      wW = max(wW, sF[r] * cw);
      c = mix(c, pm, cw);
    }
    for (int s = 0; s < 4; s++) {
      if (s >= np) break;
      if (s <= r) continue;
      vec4 q = jAt(sPb[s]);
      float fl = abs(r0.z - q.z) < 0.5 || abs(r0.w - q.w) < 0.5 ? 1.0 : abs(r0.z - q.w) < 0.5 || abs(r0.w - q.z) < 0.5 ? -1.0 : 0.0;
      float ys = sF[s] * (1.0 - smoothstep(0.0, 3.0 * pxW, sDist[s] - dShared));
      wW = max(wW, smoothstep(0.0, reach * reach, -sSd[r] * sSd[s] * fl) * (1.0 - smoothstep(0.52, 1.56, sDist[r] + sDist[s] - 2.0 * reach)) * min(sF[r] * yr, ys));
    }
  }
  c.rgb = mix(c.rgb, uKHlPulse.rgb * c.a, wW);
  return c;
}

in vec2 vPos;
flat in float vRec;
in float vLook;
in float vFlank;
flat in vec4 vMaskId;
in vec4 vColor;

out vec4 finalColor;

uniform highp sampler2D uGapData;

uniform highp sampler2D uSamp;
uniform vec4 uFabricGap;
vec2 sampAt(int i) {
  int t = i >> 1;
  vec4 q = texelFetch(uSamp, ivec2(t & 1023, t >> 10), 0);
  return (i & 1) == 0 ? q.xy : q.zw;
}



void gapSeg(highp vec2 p, highp vec2 a, highp vec2 b, int k,
    inout highp float best, inout int bk) {
  highp vec2 ab = b - a;
  highp vec2 pa = p - a;
  highp float l2 = dot(ab, ab);
  highp float h = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
  highp vec2 q = pa - ab * h;
  highp float d2 = dot(q, q);
  if (d2 < best) {
    best = d2;
    bk = k;
  }
}

// FULL: also skips segment indices skipLo..skipHi (the far-branch pass;
// empty when skipLo > skipHi) and, when ex > 0 (self-crossings), a segment
// whose nearest point's chain arc lies within ex of the fragment's arc fa
// (s0/st: the range's arc parameterization in sampled steps; per: the
// ring period, 0 on open chains).
void gapSegFull(highp vec2 p, highp vec2 a, highp vec2 b, int k,
    highp float ex, highp float fa, highp float s0, highp float st,
    highp float per, int skipLo, int skipHi,
    inout highp float best, inout int bk) {
  if (k >= skipLo && k <= skipHi) return;
  highp vec2 ab = b - a;
  highp vec2 pa = p - a;
  highp float l2 = dot(ab, ab);
  highp float h = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
  if (ex > 0.0) {
    highp float da = s0 + (float(k) + h) * st - fa;
    if (per > 0.0) da -= per * floor(da / per + 0.5);
    if (abs(da) < ex) return;
  }
  highp vec2 q = pa - ab * h;
  highp float d2 = dot(q, q);
  if (d2 < best) {
    best = d2;
    bk = k;
  }
}

ivec4 gapRange(vec4 t4, vec4 t9) {
  return ivec4(int(t4.y + 0.5), max(int(t9.x + 0.5), 1),
    max(int(t9.y + 0.5), 1), int(floor(t4.z + 0.5)));
}
highp vec2 gapAt(int r, out int i, ivec4 g, bool ring) {
  i = ring ? ((r % g.z) + g.z) % g.z : clamp(r, 0, g.z - 1);
  return sampAt(g.x + i);
}
highp vec2 gapNext(inout int r, inout int i, ivec4 g, bool ring) {
  r += g.y;
  i += g.y;
  i = ring ? (i < g.z ? i : i - g.z) : clamp(r, 0, g.z - 1);
  return sampAt(g.x + i);
}

// Sampled point j of a range (t4 = [selfExcl, overBase, kStart, arcPer],
// t9 = [stride, count, closed, -]): rings wrap, open chains clamp (never
// a last-to-first chord).
vec2 gapOverPt(vec4 t4, vec4 t9, int j) {
  ivec4 g = gapRange(t4, t9);
  int i;
  return gapAt(g.w + j * g.y, i, g, t9.z > 0.5);
}

// Nearest point of the sampled range within sqrt(best) (best is the
// squared reach on entry); the nearest segment (-1: none within reach)
// comes back through bk. Fast form: no exclusions.
void gapNearestFast(int row, int nCh, highp vec2 p,
    highp float sure2, highp vec4 t4, highp vec4 t9, int nPts,
    inout highp float best, inout int bk) {
  bool brute = uFabricGap.z > 0.5;
  int nSeg = max(nPts - 1, 0);
  ivec4 g = gapRange(t4, t9);
  bool ring = t9.z > 0.5;
  for (int c = 0; c < 8; c++) {
    if (c >= nCh) break;
    if (!brute && best < sure2) break;
    int k0 = c * 8;
    if (!brute) {
      highp vec4 cc = texelFetch(uGapData, ivec2(10 + c, row), 0);
      highp float lb = length(p - cc.xy) - cc.z;
      if (lb > 0.0 && lb * lb >= best) continue;
    }
    int r = g.w + k0 * g.y, i;
    highp vec2 a = gapAt(r, i, g, ring);
    for (int j = 0; j < 8; j++) {
      int k = k0 + j;
      if (k >= nSeg) break;
      highp vec2 b = gapNext(r, i, g, ring);
      gapSeg(p, a, b, k, best, bk);
      a = b;
    }
  }
}

void gapNearestFull(int row, int nCh, highp vec2 p,
    highp float ex, highp float fa, highp float s0, highp float st,
    highp float per, int skipLo, int skipHi,
    highp float sure2, highp vec4 t4, highp vec4 t9, int nPts,
    inout highp float best, inout int bk) {
  bool brute = uFabricGap.z > 0.5;
  int nSeg = max(nPts - 1, 0);
  ivec4 g = gapRange(t4, t9);
  bool ring = t9.z > 0.5;
  for (int c = 0; c < 8; c++) {
    if (c >= nCh) break;
    if (!brute && best < sure2) break;
    int k0 = c * 8;
    // A chunk wholly inside the skipped index range adds nothing.
    if (!brute && k0 >= skipLo && min(k0 + 7, nSeg - 1) <= skipHi) {
      continue;
    }
    if (!brute) {
      highp vec4 cc = texelFetch(uGapData, ivec2(10 + c, row), 0);
      highp float lb = length(p - cc.xy) - cc.z;
      if (lb > 0.0 && lb * lb >= best) continue;
    }
    int r = g.w + k0 * g.y, i;
    highp vec2 a = gapAt(r, i, g, ring);
    for (int j = 0; j < 8; j++) {
      int k = k0 + j;
      if (k >= nSeg) break;
      highp vec2 b = gapNext(r, i, g, ring);
      gapSegFull(p, a, b, k, ex, fa, s0, st, per, skipLo, skipHi, best, bk);
      a = b;
    }
  }
}
bool gapProbe() {
  return uFabricGap.y > 0.5;
}


// A slot's effective strength (texel 1.w; see the header): gated slots
// ramp in from their show time on the knot clock (uKFx.z = fxNow); with the
// FX clock stopped (uKFx.w = 0) every gate has long opened. Needs the knot
// uniforms and CROSSING_FADE_IN (paint_glsl.ts) declared first.
highp float gapStrength(highp float s) {
  if (s >= 0.0) return s;
  if (uKFx.w < 0.5) return 1.0;
  highp float x = clamp((uKFx.z + s + 1.0) / CROSSING_FADE_IN, 0.0, 1.0);
  return x * x * (3.0 - 2.0 * x);
}



uniform vec4 uKExplore;
// The end look's coverage at a point of a FRONTIER fade: u = progress 0 -> 1
// through it (< 0: not in a frontier fade), s = world arc from the solid end,
// lf = the fade's world arc length (K397), lat = vUV.y - 0.5 (0 on the
// centerline), sideFw = vUV.y per pixel. Returns
// v itself for the fade and halo looks and outside a frontier. The glow
// look's tint is the caller's (it colors the thread; it is not coverage).
// Shared by the thread (main) and the shaped cut (K268). CPU twin:
// paint_math.ts kExploreLookCpu. K76 stage 2d (question 9): under High
// contrast (uKExplore.x 2) the dots draw at full strength, and kExDot says
// whether the point's nearest shape is a dot (1) or the cap (0; 0 in every
// other look), which main paints pure white.
highp float kExDot;
// K397 THE DOTS' SHAPE (Levi's call (c)): the signed world distance from a
// point of a frontier fade (s along from the solid end, la across, lf the
// fade's length) to the nearest of the cap (half an ellipse, 0.5 tw across
// and 0.5 tw g along) and two dots at EXPLORE_DOT_AT of the fade, radii
// EXPLORE_DOT_R tw g; g = min(1, lf / (EXPLORE_DOTS_SPAN tw)) fits them in.
// Sets kExDot. Used by the thread's look and the dots' cut. CPU twin:
// paint_math.ts kExDotsSdCpu.
highp float kExDotsSd(highp float s, highp float la, highp float lf) {
  highp float tw = uKExplore.w;
  highp float g = clamp(lf / (2.15000 * tw), 1e-3, 1.0);
  highp float ca = 0.5 * tw * g;
  highp float cb = 0.5 * tw;
  highp float k0 = length(vec2(s / ca, la / cb));
  highp float k1 = length(vec2(s / (ca * ca), la / (cb * cb)));
  highp float dCap = k1 > 1e-6 ? k0 * (k0 - 1.0) / k1 : -ca;
  highp float dDot = min(
    length(vec2(s - 0.44000 * lf, la)) - 0.24720 * tw * g,
    length(vec2(s - 0.88000 * lf, la)) - 0.19440 * tw * g);
  kExDot = dDot < dCap ? 1.0 : 0.0;
  return min(dCap, dDot);
}
highp float kExploreLook(int look, highp float v, highp float u, highp float s,
    highp float lf, highp float lat, highp float sideFw, highp float pxW) {
  kExDot = 0.0;
  if (u < 0.0 || look < 2) return v;
  highp float tw = uKExplore.w;
  if (look == 2) {
    // GLOW: the alpha fade starts later so the highlight reads.
    return 1.0 - kSmooth((u - 0.4) / 0.6);
  }
  if (look == 4) {
    // FRAY: the thread unravels into three thinning fibers that fade.
    highp float fl = lat * 2.0;
    highp float cov = 0.0;
    for (int i = -1; i <= 1; i++) {
      highp float fi = float(i);
      highp float cf = fi * (0.5 + 0.3 * u) + 0.12 * u * sin(s * 7.0 + fi * 2.1);
      highp float wf = mix(0.34, 0.1, u);
      cov = max(cov, clamp((wf - abs(fl - cf)) / max(4.0 * sideFw, 1e-4) + 0.5, 0.0, 1.0));
    }
    cov = mix(1.0, cov, kSmooth(u / 0.12));
    return cov * (1.0 - kSmooth((u - 0.5) / 0.5));
  }
  // DOTS (3) and BEACON (5, plus its halo sprite): the solid thread ends in
  // a cap, then two dots that fade (K397: always two, sized to the fade).
  highp float dd = kExDotsSd(s, lat * tw, lf);
  return clamp(-dd / pxW + 0.5, 0.0, 1.0) * (uKExplore.x > 1.5 ? 1.0 : 1.0 - 0.55 * u * u);
}
// K268 THE SHAPED CUT: the over thread's coverage at its chain arc A (the
// slot polyline's frame), from the slot's profile texels (gap_mask.ts
// GAP_PROF_BASE): up to two ramps R = [aS, F, dK, tK] (the solid end's arc,
// the fade's signed arc length, one interior knot of the ctrl-linear fade),
// combined by MIN (one piece's two ends) or best-of (two pieces: kExploreAt's
// rule, ties preferring the solid one), with the end look at a frontier on
// the centerline (lat 0). CPU twin: paint_math.ts exploreCutCoverCpu.
// K397 THE DOTS' CUT: in the dots and beacon looks a frontier fade cuts by
// the dots' own shape, at the fragment's own distance lat from the over
// centerline. The cover is then only the look's strength, kExCutOn is set
// and kExCutSd holds kExDotsSd there, and gapKeepAt measures its casing
// from that shape (EXPLORE_GAP_SHAPE_GLSL): a disc of radius r + casing
// around each dot and the cap's half ellipse plus casing, also past the
// fade's end (t 1), where the second dot's casing reaches.
bool kExCutOn;
highp float kExCutSd;
// K268 FAR-BRANCH (stage 2 item 2, last part): a shaped slot's per-branch
// state for the vis-weighted far-branch blend (below, at gapKeepAt's
// smooth-min). exCoverNear / exStrength are the near branch's coverage and
// the slot's clock strength (gst = exStrength * exCoverNear, set by
// EXPLORE_GAP_CUT); exBlendCut / exFarOn carry the blended weighted cut
// the keep line then applies instead of the near branch's own.
highp float exCoverNear;
highp float exStrength;
highp float exBlendCut;
bool exFarOn;
// The geometric cut (casing + fade + window-end ramp, times inWinInFoot;
// a fan adds its silhouette) at centerline distance dv, with gapKeepAt's
// own margin / fadeP / winM / fade at the near point. Monotone
// non-increasing in dv. Used only by the far-branch blend.
highp float exCutAtDist(highp float dv, highp float hOv, highp float marg,
    highp float fadePv, highp float pxWv, highp float winMv,
    highp float fadeRaw, highp float inWF, bool isFan) {
  highp float e = dv - hOv - marg;
  highp float k = clamp((e + 0.5 * pxWv) / max(fadePv, pxWv), 0.0, 1.0);
  k = k * k * (3.0 - 2.0 * k);
  highp float fs = clamp(winMv / max(0.5 * fadeRaw, pxWv), 0.0, 1.0);
  fs = mix(1.0, fs * fs * (3.0 - 2.0 * fs), clamp(e / pxWv, 0.0, 1.0));
  highp float c = (1.0 - k) * inWF * fs;
  if (isFan) c = max(c, 1.0 - clamp((dv - hOv + pxWv) / pxWv + 0.5, 0.0, 1.0));
  return c;
}
highp float exploreCutCover(int row, int fl, highp float A, highp float lat, highp float pxW) {
  kExCutOn = false;
  int look = int(uKExplore.y + 0.5);
  bool dots = look == 3 || look == 5;
  bool mx = (fl & 16) != 0;
  highp float best = mx ? -1.0 : 2.0;
  highp float bu = -1.0;
  highp float bs = 0.0;
  highp float bf = 0.0;
  for (int r = 0; r < 2; r++) {
    if ((fl & (1 << r)) == 0) continue;
    highp vec4 R = texelFetch(uGapData, ivec2(22 + r, row), 0);
    highp float d = (A - R.x) / R.y;
    highp float v = 1.0;
    highp float u = -1.0;
    if (d > 0.0) {
      highp float t = d < R.z
        ? d * (R.w / R.z)
        : R.w + (d - R.z) * ((1.0 - R.w) / max(1.0 - R.z, 1e-6));
      t = min(t, 1.0);
      v = 1.0 - t * t * (3.0 - 2.0 * t);
      if ((t < 1.0 || dots) && (fl & (4 << r)) != 0) u = t;
    }
    if (mx ? (v > best || (v == best && u < 0.0)) : v < best) {
      best = v;
      bu = u;
      bs = abs(A - R.x);
      bf = abs(R.y);
    }
  }
  if (best > 1.0) return 1.0;
  if (best < 0.0) return 0.0;
  if (dots && bu >= 0.0) {
    kExCutOn = true;
    kExCutSd = kExDotsSd(bs, lat, bf);
    return uKExplore.x > 1.5 ? 1.0 : 1.0 - 0.55 * bu * bu;
  }
  return kExploreLook(look, best, bu, bs, bf, 0.0,
    pxW / max(uKExplore.w, 1e-6), pxW);
}
highp float gapKeepAt(highp float pxW, highp vec2 p, highp float turn,
    highp vec2 tanv, highp vec4 ids) {
  if (all(lessThan(abs(ids + 1.0), vec4(0.5)))) return 1.0;
  if (uFabricGap.x < 0.5) return 1.0;
  // Every slot of a ribbon fragment windows the fragment's own chain, so
  // one turn serves them all.
  bool fan = true;
  highp float keep = 1.0;
  for (int s = 0; s < 4; s++) {
    // Fully hidden already: no later slot can change the answer.
    if (keep <= 0.002) break;
    highp float idf = ids[s];
    if (abs(idf + 1.0) < 0.5) continue; // -1 = no slot.
    // ids >= 0: the full mask (ribbons; a fan that IS the under thread's
    // material - a free tip's cap). ids <= -2 encode slot (-id - 2) for a
    // JUNCTION fan: the over silhouette only (see below).
    bool full = idf > -0.5;
    int row = int(full ? idf + 0.5 : -idf - 1.5) + 1;
    // REJECT on texel 0 alone: the bounding circle grown by the reach of
    // interest (a disabled slot's radius is negative).
    highp vec4 t0 = texelFetch(uGapData, ivec2(0, row), 0);
    highp float rr = full ? t0.z + 2.0 * pxW : t0.w + pxW;
    highp vec2 db = p - t0.xy;
    if (rr <= 0.0 || dot(db, db) > rr * rr) continue;
