#version 300 es
#define SHADER_NAME pluck-still-explore-vertex
precision highp float;

precision highp float;

in vec2 aPosition;
in vec2 aUV;
in vec4 aAux;
in vec4 aGap;
in vec4 aGapId;

out float vLat;
out float vA;
out vec2 vPos;
out float vTurn;
out vec2 vTan;
flat out vec4 vMaskId;
out vec4 vColor;

uniform mat3 uProjectionMatrix;
uniform mat3 uWorldTransformMatrix;
uniform vec4 uWorldColorAlpha;
uniform mat3 uTransformMatrix;
uniform vec4 uColor;

void main(void) {
  mat3 mvp = uProjectionMatrix * uWorldTransformMatrix * uTransformMatrix;
  gl_Position = vec4((mvp * vec3(aPosition, 1.0)).xy, 0.0, 1.0);
  vLat = aUV.x;
  vA = aAux.w;
  vPos = aPosition;
  vTurn = aGap.x;
  vTan = aGap.yz;
  vMaskId = aGapId;
  vColor = uColor * uWorldColorAlpha;
}

