#version 300 es
#define SHADER_NAME pluck-still-explore-fragment
precision mediump float;

precision highp float;
precision highp int;
precision highp sampler2D;

uniform vec4 uKBase;
uniform vec4 uKFx;
uniform vec4 uKFx2;
uniform vec4 uKShape;
uniform vec4 uKInk;
uniform vec4 uKKnots[8];
uniform vec4 uKGamut;
uniform vec4 uKSect;
uniform vec4 uKPaint;
uniform vec4 uKPulse;
uniform vec4 uKReach;
uniform vec4 uKGold;
uniform vec4 uKLook;
uniform vec4 uKPath;
uniform vec4 uKPathB;
uniform vec4 uKHlPulse;
uniform vec4 uKHlHover;
uniform vec4 uKHlFray;
uniform vec4 uKBorder;


const float REVEAL_TAPER_ARC = 0.3;
const float INK_TAPER_WORLD = 0.6;
const float REVEAL_CROSSING_MIN = 0.98;
const float REVEAL_GLOW_ARC = 1.15;
const float RAINBOW_GLOW_ARC = 2.4;
const float RAINBOW_GLOW_HOLD = 0.45;
const float BURN_EMBER_END = 0.4;
const float BURN_CHAR_END = 0.9;
const float BURN_RECOVER_END = 1.3;
const float BURN_HOT_ARC = 0.45;
const float ROOTS_START = 0.05;
const float ROOTS_FADE = 1.0;
const float RAINBOW_HOLD = 0.12;
const float RAINBOW_FADE = 0.65;
const float DUST_FADE_IN = 0.55;
const float COMET_FADE_IN = 1.0;
const float RAINBOW_SWELL = 1.0;
const float RAINBOW_SWELL_MIN_P = 0.2;
const float FAN_SOLID_START = 0.55;
const float FX_SOLID_EPS = 0.03;
const float CROSSING_FADE_IN = 0.36;
const float PULSE_FLOOR_REACH = 2.0;
const float CREST_WIDTH = 0.72;
const float PULSE_SPEED = 1.6;
const float PULSE_FLOOR = 0.38;
const float PULSE_CORE_BOOST = 0.62;
const float PULSE_CORE_RADIUS = 0.55;
const float CREST_RAMP = 0.5;
const float PULSE_END_WINDOW = 0.45;
const float PULSE_OUT_LEAD = 0.3;
const float PULSE_FADE_IN = 0.45;
const float HOVER_PULSE_W = 5.2;
const float PULSE_MIN_V = 0.004;
const float PULSE_REACH_FADE = 1.0;
const float RIM_END_SHARE = 0.6;
const float RIM_EDGE = 0.85;
const float K_BAND = 0.9315315315315315;
const float HC_LINE = 0.3;
const float HC_LINE_SOFT = 0.1;
const float HC_CORE = 0.65;
const float HC_CORE_SOFT = 0.15;
const float HC_CHEV_PERIOD = 0.8;
const float HC_CHEV_LEAN = 0.3;
const float RAMP_EASE_FULL = 1.0;
const int PI_SPAN = 1;
const int PI_CAP = 2;
const int PI_PULSE = 3;
const int PI_RIM = 4;
const int IF_INWARD = 1;
const int IF_HOVER = 4;
const int RF_GAMUT = 1;
const int RF_SWEEP = 2;
const int RF_NOISE = 4;
const int RF_RAMP_A = 8;
const int RF_RAMP_B = 16;
const float K_TAU = 6.283185307179586;
const float K_INV_TAU = 0.15915494309189535;

in float vLat;
in float vA;
in vec2 vPos;
in float vTurn;
in vec2 vTan;
flat in vec4 vMaskId;
in vec4 vColor;

out vec4 finalColor;

// (half-width h, partner casing band, ghost tint, unused)
uniform vec4 uPluck;

uniform highp sampler2D uGapData;

uniform highp sampler2D uSamp;
uniform vec4 uFabricGap;
vec2 sampAt(int i) {
  int t = i >> 1;
  vec4 q = texelFetch(uSamp, ivec2(t & 1023, t >> 10), 0);
  return (i & 1) == 0 ? q.xy : q.zw;
}



void gapSeg(highp vec2 p, highp vec2 a, highp vec2 b, int k,
    inout highp float best, inout int bk) {
  highp vec2 ab = b - a;
  highp vec2 pa = p - a;
  highp float l2 = dot(ab, ab);
  highp float h = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
  highp vec2 q = pa - ab * h;
  highp float d2 = dot(q, q);
  if (d2 < best) {
    best = d2;
    bk = k;
  }
}

// FULL: also skips segment indices skipLo..skipHi (the far-branch pass;
// empty when skipLo > skipHi) and, when ex > 0 (self-crossings), a segment
// whose nearest point's chain arc lies within ex of the fragment's arc fa
// (s0/st: the range's arc parameterization in sampled steps; per: the
// ring period, 0 on open chains).
void gapSegFull(highp vec2 p, highp vec2 a, highp vec2 b, int k,
    highp float ex, highp float fa, highp float s0, highp float st,
    highp float per, int skipLo, int skipHi,
    inout highp float best, inout int bk) {
  if (k >= skipLo && k <= skipHi) return;
  highp vec2 ab = b - a;
  highp vec2 pa = p - a;
  highp float l2 = dot(ab, ab);
  highp float h = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
  if (ex > 0.0) {
    highp float da = s0 + (float(k) + h) * st - fa;
    if (per > 0.0) da -= per * floor(da / per + 0.5);
    if (abs(da) < ex) return;
  }
  highp vec2 q = pa - ab * h;
  highp float d2 = dot(q, q);
  if (d2 < best) {
    best = d2;
    bk = k;
  }
}

ivec4 gapRange(vec4 t4, vec4 t9) {
  return ivec4(int(t4.y + 0.5), max(int(t9.x + 0.5), 1),
    max(int(t9.y + 0.5), 1), int(floor(t4.z + 0.5)));
}
highp vec2 gapAt(int r, out int i, ivec4 g, bool ring) {
  i = ring ? ((r % g.z) + g.z) % g.z : clamp(r, 0, g.z - 1);
  return sampAt(g.x + i);
}
highp vec2 gapNext(inout int r, inout int i, ivec4 g, bool ring) {
  r += g.y;
  i += g.y;
  i = ring ? (i < g.z ? i : i - g.z) : clamp(r, 0, g.z - 1);
  return sampAt(g.x + i);
}

// Sampled point j of a range (t4 = [selfExcl, overBase, kStart, arcPer],
// t9 = [stride, count, closed, -]): rings wrap, open chains clamp (never
// a last-to-first chord).
vec2 gapOverPt(vec4 t4, vec4 t9, int j) {
  ivec4 g = gapRange(t4, t9);
  int i;
  return gapAt(g.w + j * g.y, i, g, t9.z > 0.5);
}

// Nearest point of the sampled range within sqrt(best) (best is the
// squared reach on entry); the nearest segment (-1: none within reach)
// comes back through bk. Fast form: no exclusions.
void gapNearestFast(int row, int nCh, highp vec2 p,
    highp float sure2, highp vec4 t4, highp vec4 t9, int nPts,
    inout highp float best, inout int bk) {
  bool brute = uFabricGap.z > 0.5;
  int nSeg = max(nPts - 1, 0);
  ivec4 g = gapRange(t4, t9);
  bool ring = t9.z > 0.5;
  for (int c = 0; c < 8; c++) {
    if (c >= nCh) break;
    if (!brute && best < sure2) break;
    int k0 = c * 8;
    if (!brute) {
      highp vec4 cc = texelFetch(uGapData, ivec2(10 + c, row), 0);
      highp float lb = length(p - cc.xy) - cc.z;
      if (lb > 0.0 && lb * lb >= best) continue;
    }
    int r = g.w + k0 * g.y, i;
    highp vec2 a = gapAt(r, i, g, ring);
    for (int j = 0; j < 8; j++) {
      int k = k0 + j;
      if (k >= nSeg) break;
      highp vec2 b = gapNext(r, i, g, ring);
      gapSeg(p, a, b, k, best, bk);
      a = b;
    }
  }
}

void gapNearestFull(int row, int nCh, highp vec2 p,
    highp float ex, highp float fa, highp float s0, highp float st,
    highp float per, int skipLo, int skipHi,
    highp float sure2, highp vec4 t4, highp vec4 t9, int nPts,
    inout highp float best, inout int bk) {
  bool brute = uFabricGap.z > 0.5;
  int nSeg = max(nPts - 1, 0);
  ivec4 g = gapRange(t4, t9);
  bool ring = t9.z > 0.5;
  for (int c = 0; c < 8; c++) {
    if (c >= nCh) break;
    if (!brute && best < sure2) break;
    int k0 = c * 8;
    // A chunk wholly inside the skipped index range adds nothing.
    if (!brute && k0 >= skipLo && min(k0 + 7, nSeg - 1) <= skipHi) {
      continue;
    }
    if (!brute) {
      highp vec4 cc = texelFetch(uGapData, ivec2(10 + c, row), 0);
      highp float lb = length(p - cc.xy) - cc.z;
      if (lb > 0.0 && lb * lb >= best) continue;
    }
    int r = g.w + k0 * g.y, i;
    highp vec2 a = gapAt(r, i, g, ring);
    for (int j = 0; j < 8; j++) {
      int k = k0 + j;
      if (k >= nSeg) break;
      highp vec2 b = gapNext(r, i, g, ring);
      gapSegFull(p, a, b, k, ex, fa, s0, st, per, skipLo, skipHi, best, bk);
      a = b;
    }
  }
}
bool gapProbe() {
  return uFabricGap.y > 0.5;
}


// A slot's effective strength (texel 1.w; see the header): gated slots
// ramp in from their show time on the knot clock (uKFx.z = fxNow); with the
// FX clock stopped (uKFx.w = 0) every gate has long opened. Needs the knot
// uniforms and CROSSING_FADE_IN (paint_glsl.ts) declared first.
highp float gapStrength(highp float s) {
  if (s >= 0.0) return s;
  if (uKFx.w < 0.5) return 1.0;
  highp float x = clamp((uKFx.z + s + 1.0) / CROSSING_FADE_IN, 0.0, 1.0);
  return x * x * (3.0 - 2.0 * x);
}

// 1 inside the arc interval [a, b] (with a short ramp), 0 outside; an
// empty interval (a >= b) is 0.
highp float gapInterval(highp float o, highp float a, highp float b) {
  if (a >= b) return 0.0;
  return clamp(min(o - a, b - o) / 0.04 + 0.5, 0.0, 1.0);
}

// How much of p lies over the ribbon (half-width h) around a PROTECT
// range in SAMP (G3-1): 1 inside, a one-pixel ramp at its edge, 0 outside
// (and for fewer than 2 sampled points). The range texel at base is
// [sampBase, kStart, nPts, stride] and the next texel its bounding circle
// [cx, cy, r, signedCount] (negative = the chain is closed, |.| = its
// sample count, for the wrap). Loop-free: the circle rejects most
// fragments, then ONE segment loop reads the samples in place - no chunk
// nesting (G1's protect cost was mostly register pressure, so the loop
// stays single).
highp float gapProtCover(int row, int base, highp vec2 p,
    highp float h, highp float pxW) {
  highp vec4 rg = texelFetch(uGapData, ivec2(base, row), 0);
  int n = int(rg.z + 0.5);
  if (n < 2) return 0.0;
  highp vec4 bc = texelFetch(uGapData, ivec2(base + 1, row), 0);
  highp float reach = h + pxW;
  highp float rr = bc.z + reach;
  highp vec2 dc = p - bc.xy;
  if (dot(dc, dc) > rr * rr) return 0.0;
  int r = int(floor(rg.y + 0.5)), i;
  ivec4 g = ivec4(int(rg.x + 0.5), max(int(rg.w + 0.5), 1),
    max(int(abs(bc.w) + 0.5), 1), 0);
  bool ring = bc.w < -0.5;
  highp vec2 a = gapAt(r, i, g, ring);
  highp float best = reach * reach;
  for (int j = 0; j < 64; j++) {
    if (j >= n - 1) break;
    highp vec2 b = gapNext(r, i, g, ring);
    highp vec2 ab = b - a;
    highp vec2 pa = p - a;
    highp float l2 = dot(ab, ab);
    highp float hh = l2 > 1e-12 ? clamp(dot(pa, ab) / l2, 0.0, 1.0) : 0.0;
    highp vec2 q = pa - ab * hh;
    best = min(best, dot(q, q));
    a = b;
  }
  return clamp((h - sqrt(best)) / pxW + 0.5, 0.0, 1.0);
}

uniform vec4 uKExplore;
highp float kSmooth(highp float x) {
  highp float c = clamp(x, 0.0, 1.0);
  return c * c * (3.0 - 2.0 * c);
}
// The end look's coverage at a point of a FRONTIER fade: u = progress 0 -> 1
// through it (< 0: not in a frontier fade), s = world arc from the solid end,
// lf = the fade's world arc length (K397), lat = vUV.y - 0.5 (0 on the
// centerline), sideFw = vUV.y per pixel. Returns
// v itself for the fade and halo looks and outside a frontier. The glow
// look's tint is the caller's (it colors the thread; it is not coverage).
// Shared by the thread (main) and the shaped cut (K268). CPU twin:
// paint_math.ts kExploreLookCpu. K76 stage 2d (question 9): under High
// contrast (uKExplore.x 2) the dots draw at full strength, and kExDot says
// whether the point's nearest shape is a dot (1) or the cap (0; 0 in every
// other look), which main paints pure white.
highp float kExDot;
// K397 THE DOTS' SHAPE (Levi's call (c)): the signed world distance from a
// point of a frontier fade (s along from the solid end, la across, lf the
// fade's length) to the nearest of the cap (half an ellipse, 0.5 tw across
// and 0.5 tw g along) and two dots at EXPLORE_DOT_AT of the fade, radii
// EXPLORE_DOT_R tw g; g = min(1, lf / (EXPLORE_DOTS_SPAN tw)) fits them in.
// Sets kExDot. Used by the thread's look and the dots' cut. CPU twin:
// paint_math.ts kExDotsSdCpu.
highp float kExDotsSd(highp float s, highp float la, highp float lf) {
  highp float tw = uKExplore.w;
  highp float g = clamp(lf / (2.15000 * tw), 1e-3, 1.0);
  highp float ca = 0.5 * tw * g;
  highp float cb = 0.5 * tw;
  highp float k0 = length(vec2(s / ca, la / cb));
  highp float k1 = length(vec2(s / (ca * ca), la / (cb * cb)));
  highp float dCap = k1 > 1e-6 ? k0 * (k0 - 1.0) / k1 : -ca;
  highp float dDot = min(
    length(vec2(s - 0.44000 * lf, la)) - 0.24720 * tw * g,
    length(vec2(s - 0.88000 * lf, la)) - 0.19440 * tw * g);
  kExDot = dDot < dCap ? 1.0 : 0.0;
  return min(dCap, dDot);
}
highp float kExploreLook(int look, highp float v, highp float u, highp float s,
    highp float lf, highp float lat, highp float sideFw, highp float pxW) {
  kExDot = 0.0;
  if (u < 0.0 || look < 2) return v;
  highp float tw = uKExplore.w;
  if (look == 2) {
    // GLOW: the alpha fade starts later so the highlight reads.
    return 1.0 - kSmooth((u - 0.4) / 0.6);
  }
  if (look == 4) {
    // FRAY: the thread unravels into three thinning fibers that fade.
    highp float fl = lat * 2.0;
    highp float cov = 0.0;
    for (int i = -1; i <= 1; i++) {
      highp float fi = float(i);
      highp float cf = fi * (0.5 + 0.3 * u) + 0.12 * u * sin(s * 7.0 + fi * 2.1);
      highp float wf = mix(0.34, 0.1, u);
      cov = max(cov, clamp((wf - abs(fl - cf)) / max(4.0 * sideFw, 1e-4) + 0.5, 0.0, 1.0));
    }
    cov = mix(1.0, cov, kSmooth(u / 0.12));
    return cov * (1.0 - kSmooth((u - 0.5) / 0.5));
  }
  // DOTS (3) and BEACON (5, plus its halo sprite): the solid thread ends in
  // a cap, then two dots that fade (K397: always two, sized to the fade).
  highp float dd = kExDotsSd(s, lat * tw, lf);
  return clamp(-dd / pxW + 0.5, 0.0, 1.0) * (uKExplore.x > 1.5 ? 1.0 : 1.0 - 0.55 * u * u);
}
// K268 THE SHAPED CUT: the over thread's coverage at its chain arc A (the
// slot polyline's frame), from the slot's profile texels (gap_mask.ts
// GAP_PROF_BASE): up to two ramps R = [aS, F, dK, tK] (the solid end's arc,
// the fade's signed arc length, one interior knot of the ctrl-linear fade),
// combined by MIN (one piece's two ends) or best-of (two pieces: kExploreAt's
// rule, ties preferring the solid one), with the end look at a frontier on
// the centerline (lat 0). CPU twin: paint_math.ts exploreCutCoverCpu.
// K397 THE DOTS' CUT: in the dots and beacon looks a frontier fade cuts by
// the dots' own shape, at the fragment's own distance lat from the over
// centerline. The cover is then only the look's strength, kExCutOn is set
// and kExCutSd holds kExDotsSd there, and gapKeepAt measures its casing
// from that shape (EXPLORE_GAP_SHAPE_GLSL): a disc of radius r + casing
// around each dot and the cap's half ellipse plus casing, also past the
// fade's end (t 1), where the second dot's casing reaches.
bool kExCutOn;
highp float kExCutSd;
// K268 FAR-BRANCH (stage 2 item 2, last part): a shaped slot's per-branch
// state for the vis-weighted far-branch blend (below, at gapKeepAt's
// smooth-min). exCoverNear / exStrength are the near branch's coverage and
// the slot's clock strength (gst = exStrength * exCoverNear, set by
// EXPLORE_GAP_CUT); exBlendCut / exFarOn carry the blended weighted cut
// the keep line then applies instead of the near branch's own.
highp float exCoverNear;
highp float exStrength;
highp float exBlendCut;
bool exFarOn;
// The geometric cut (casing + fade + window-end ramp, times inWinInFoot;
// a fan adds its silhouette) at centerline distance dv, with gapKeepAt's
// own margin / fadeP / winM / fade at the near point. Monotone
// non-increasing in dv. Used only by the far-branch blend.
highp float exCutAtDist(highp float dv, highp float hOv, highp float marg,
    highp float fadePv, highp float pxWv, highp float winMv,
    highp float fadeRaw, highp float inWF, bool isFan) {
  highp float e = dv - hOv - marg;
  highp float k = clamp((e + 0.5 * pxWv) / max(fadePv, pxWv), 0.0, 1.0);
  k = k * k * (3.0 - 2.0 * k);
  highp float fs = clamp(winMv / max(0.5 * fadeRaw, pxWv), 0.0, 1.0);
  fs = mix(1.0, fs * fs * (3.0 - 2.0 * fs), clamp(e / pxWv, 0.0, 1.0));
  highp float c = (1.0 - k) * inWF * fs;
  if (isFan) c = max(c, 1.0 - clamp((dv - hOv + pxWv) / pxWv + 0.5, 0.0, 1.0));
  return c;
}
highp float exploreCutCover(int row, int fl, highp float A, highp float lat, highp float pxW) {
  kExCutOn = false;
  int look = int(uKExplore.y + 0.5);
  bool dots = look == 3 || look == 5;
  bool mx = (fl & 16) != 0;
  highp float best = mx ? -1.0 : 2.0;
  highp float bu = -1.0;
  highp float bs = 0.0;
  highp float bf = 0.0;
  for (int r = 0; r < 2; r++) {
    if ((fl & (1 << r)) == 0) continue;
    highp vec4 R = texelFetch(uGapData, ivec2(22 + r, row), 0);
    highp float d = (A - R.x) / R.y;
    highp float v = 1.0;
    highp float u = -1.0;
    if (d > 0.0) {
      highp float t = d < R.z
        ? d * (R.w / R.z)
        : R.w + (d - R.z) * ((1.0 - R.w) / max(1.0 - R.z, 1e-6));
      t = min(t, 1.0);
      v = 1.0 - t * t * (3.0 - 2.0 * t);
      if ((t < 1.0 || dots) && (fl & (4 << r)) != 0) u = t;
    }
    if (mx ? (v > best || (v == best && u < 0.0)) : v < best) {
      best = v;
      bu = u;
      bs = abs(A - R.x);
      bf = abs(R.y);
    }
  }
  if (best > 1.0) return 1.0;
  if (best < 0.0) return 0.0;
  if (dots && bu >= 0.0) {
    kExCutOn = true;
    kExCutSd = kExDotsSd(bs, lat, bf);
    return uKExplore.x > 1.5 ? 1.0 : 1.0 - 0.55 * bu * bu;
  }
  return kExploreLook(look, best, bu, bs, bf, 0.0,
    pxW / max(uKExplore.w, 1e-6), pxW);
}
highp float gapKeepAt(highp float pxW, highp vec2 p, highp float turn,
    highp vec2 tanv, highp vec4 ids) {
  if (all(lessThan(abs(ids + 1.0), vec4(0.5)))) return 1.0;
  if (uFabricGap.x < 0.5) return 1.0;
  // Every slot of a ribbon fragment windows the fragment's own chain, so
  // one turn serves them all.
  bool fan = false;
  highp float keep = 1.0;
  for (int s = 0; s < 4; s++) {
    // Fully hidden already: no later slot can change the answer.
    if (keep <= 0.002) break;
    highp float idf = ids[s];
    if (abs(idf + 1.0) < 0.5) continue; // -1 = no slot.
    // ids >= 0: the full mask (ribbons; a fan that IS the under thread's
    // material - a free tip's cap). ids <= -2 encode slot (-id - 2) for a
    // JUNCTION fan: the over silhouette only (see below).
    bool full = idf > -0.5;
    int row = int(full ? idf + 0.5 : -idf - 1.5) + 1;
    // REJECT on texel 0 alone: the bounding circle grown by the reach of
    // interest (a disabled slot's radius is negative).
    highp vec4 t0 = texelFetch(uGapData, ivec2(0, row), 0);
    highp float rr = full ? t0.z + 2.0 * pxW : t0.w + pxW;
    highp vec2 db = p - t0.xy;
    if (rr <= 0.0 || dot(db, db) > rr * rr) continue;
    highp vec4 t1 = texelFetch(uGapData, ivec2(1, row), 0);
    highp vec4 t2 = texelFetch(uGapData, ivec2(2, row), 0);
    highp float hO = t2.z;
    highp float gst = gapStrength(t1.w);
    highp float inWin = 1.0;
    highp float inFoot = 1.0;
    // Arc distance to the nearer window end (fade ramp below).
    highp float winM = 1e6;
    // Signed arc offset along the under thread (fans: projected).
    highp float offA = 0.0;
    highp float fa = 0.0;
    highp vec4 t5 = vec4(0.0);
    highp vec4 t6 = vec4(0.0);
      // Arc offset from the window center along the under chain
      // (wrapped on closed rings), then the window test with a one-pixel
      // AA ramp at its ends.
      fa = turn * t1.x;
      highp float off = fa - t1.y;
      if (t1.z > 0.0) off -= t1.z * floor(off / t1.z + 0.5);
      offA = off;
      highp float m = min(off + t2.x, t2.y - off);
      if (m <= -pxW) continue;
      inWin = clamp(m / pxW + 0.5, 0.0, 1.0);
      winM = m;
    highp vec4 t3 = texelFetch(uGapData, ivec2(3, row), 0);
    int fl = int(t3.w + 0.5);
    bool perp = (fl & 1) != 0;
    int n = int(t2.w + 0.5);
    highp float kLast = float(max(n - 1, 0));
    int nCh = n >= 2 ? (n - 2) / 8 + 1 : 0;
    highp vec4 t4 = texelFetch(uGapData, ivec2(4, row), 0);
    highp vec4 t9 = texelFetch(uGapData, ivec2(9, row), 0);
    highp float ex = 0.0;
    highp float s0 = 0.0;
    highp float st = 0.0;
    highp float per = 0.0;
    if ((fl & 2) != 0 && !fan) {
      ex = t4.x;
      s0 = float(int(floor(t4.z + 0.5))) * t4.w;
      st = float(max(int(t9.x + 0.5), 1)) * t4.w;
      per = t1.z;
    }
    // REACH of interest (texel 0 holds it grown by the bounding radius):
    // beyond it nothing this slot does is visible. Inside SURE the
    // fragment is hidden whatever the margin, protect, fade or smooth-min
    // say (the silhouette always hides; the fan cut is inset one pixel
    // more), so the search may stop there.
    highp float reach = full ? hO + (t0.z - t0.w) + 2.0 * pxW : hO + pxW;
    // Zoom-aware tolerance (G3-1): the sure exit's inset floors at one
    // SAMP sample's arc. Not at the stride (K573 step 2): every d below
    // comes from the same strided walk, so a pixel of inset already keeps
    // the verdict, and a stride-3 inset left a thin thread no sure zone.
    highp float tol = max(pxW, t4.w);
    highp float sure = hO - ((full && !fan) ? 1.0 : 1.5) * tol;
    highp float sure2 = sure > 0.0 ? sure * sure : 0.0;
    bool exShaped = full && !fan && (fl & 4) != 0 && uKExplore.x > 0.5;
    exFarOn = false;
    if (exShaped) sure2 = 0.0;
    highp float best = reach * reach;
    int bk = -1;
    if (n <= 1) {
      // The marker disc (n 0: texel 5's center) or a single sampled point.
      highp vec2 cpt = n == 0
        ? texelFetch(uGapData, ivec2(5, row), 0).zw
        : gapOverPt(t4, t9, 0);
      highp vec2 dq = p - cpt;
      best = dot(dq, dq);
      bk = 0;
      if (best >= reach * reach) continue;
    } else if (ex > 0.0) {
      gapNearestFull(row, nCh, p, ex, fa, s0, st, per, 1, 0,
        sure2, t4, t9, n, best, bk);
    } else {
      gapNearestFast(row, nCh, p, sure2, t4, t9, n, best, bk);
    }
    if (bk < 0) continue; // Nothing of this slot within reach.
    if (exShaped) {
      highp vec4 exT4 = texelFetch(uGapData, ivec2(4, row), 0);
      highp vec4 exT9 = texelFetch(uGapData, ivec2(9, row), 0);
      highp vec2 exP0 = gapOverPt(exT4, exT9, bk);
      highp vec2 exP1 = gapOverPt(exT4, exT9, bk + 1);
      highp vec2 exAb = exP1 - exP0;
      highp float exBl = dot(exAb, exAb);
      highp float exBt = exBl > 1e-12 ? clamp(dot(p - exP0, exAb) / exBl, 0.0, 1.0) : 0.0;
      highp float exA = (exT4.z + (float(bk) + exBt) * exT9.x) * exT4.w;
      highp vec4 exP2 = texelFetch(uGapData, ivec2(24, row), 0);
      exCoverNear = exploreCutCover(row, int(exP2.y + 0.5), exA, sqrt(best), pxW);
      exStrength = gapStrength(exP2.x);
      gst = exStrength * exCoverNear;
      if (gst <= 0.0) continue;
    }
    if (best < sure2) {
      keep = min(keep, 1.0 - (full ? inWin * inFoot : 1.0) * gst);
      continue;
    }
    // PROTECT: where this thread covers another one at a neighboring
    // crossing it keeps everything but the silhouette (see the header) -
    // inside the arc interval, over that thread's ribbon only. Evaluated
    // here, where few values are live; one inlined cover loop serves both
    // sides (the presence of the code, not its execution, is most of its
    // cost: register pressure).
    highp float pr = 0.0;
    if (!fan) {
      highp vec4 t7 = texelFetch(uGapData, ivec2(7, row), 0);
      highp float pn = gapInterval(offA, t7.x, t7.y);
      highp float pp = gapInterval(offA, t7.z, t7.w);
      for (int sd = 0; sd < 2; sd++) {
        highp float pi = sd == 0 ? pn : pp;
        if (pi <= 0.0) continue;
        pr = max(pr, pi * gapProtCover(row,
          18 + sd * 2, p, hO, pxW) * (sd == 0 ? t3.x : t9.w));
      }
      t5 = texelFetch(uGapData, ivec2(5, row), 0);
      t6 = texelFetch(uGapData, ivec2(6, row), 0);
    }
    highp vec4 t8 = texelFetch(uGapData, ivec2(8, row), 0);
    // Over tangent at the nearest point: central-difference tangents at
    // the nearest segment's ends, blended by the nearest parameter (a
    // per-segment direction steps at every vertex - visible as kinks in
    // the arc-length margin at tight over bends). Only the arc margin and
    // the fade read it.
    highp vec2 to = vec2(1.0, 0.0);
    bool needTan = full && (!perp || t8.y > 0.0);
    highp vec2 tu = t6.xy;
    if (n >= 2 && needTan) {
      if (!fan) {
        highp float tl = length(tanv);
        if (tl > 1e-3) tu = tanv / tl;
      }
      highp vec2 pm = gapOverPt(t4, t9, bk - 1);
      highp vec2 p0 = gapOverPt(t4, t9, bk);
      highp vec2 p1 = gapOverPt(t4, t9, bk + 1);
      highp vec2 pp = gapOverPt(t4, t9, bk + 2);
      // The nearest parameter on segment bk (zero-length: 0).
      highp vec2 abk = p1 - p0;
      highp float blk = dot(abk, abk);
      highp float bt = blk > 1e-12 ? clamp(dot(p - p0, abk) / blk, 0.0, 1.0) : 0.0;
      highp vec2 ta = p1 - pm;
      highp vec2 tb = pp - p0;
      ta /= max(length(ta), 1e-6);
      tb /= max(length(tb), 1e-6);
      to = mix(ta, tb, bt);
      to /= max(length(to), 1e-6);
    }
    highp float d = sqrt(best);
    // A one-point polyline (marker disc) has no direction: radial, sin 1.
    highp float sinT =
      n >= 2 && needTan ? abs(tu.x * to.y - tu.y * to.x) : 1.0;
    // Junction clearance, PER SIDE of the crossing (solved on the CPU from
    // the room a fused joint leaves, as the erase era capped its lanes):
    // margin and fade shrink only by the shortfall. The side switch at
    // offA = 0 lies inside the over silhouette, where everything hides.
    bool posSide = offA >= 0.0;
    highp float margin =
      (perp ? t8.x : t8.x * sinT) * (posSide ? t6.w : t6.z);
    // The FADE stays an arc length along the under thread in both looks
    // (fadeLength's meaning): perpendicular it is fade * sin - floored in
    // the casing look, where a parallel run has no along-thread exit.
    highp float fadeP =
      t8.y * (perp ? max(sinT, 0.2) : sinT) * (posSide ? t5.y : t5.x);
    margin *= 1.0 - pr;
    fadeP *= 1.0 - pr;
    highp float sk = t8.z;
    if (full && n >= 2 && sk > 0.0) {
      // FAR-BRANCH SMOOTH-MIN, edge band only: the blend can only lower d
      // by up to sminK / 4, so fragments already hidden or far outside are
      // settled without it.
      highp float lo = hO + margin - 0.5 * pxW;
      highp float hi = hO + margin + max(fadeP, pxW) + 0.25 * sk;
      if (d > lo && d < hi) {
        int farK = int(t8.w + 0.5);
        highp float best2 = (d + sk) * (d + sk);
        int bk2 = -1;
        gapNearestFull(row, nCh, p, ex, fa, s0, st, per,
          bk - farK, bk + farK, 0.0, t4, t9, n, best2, bk2);
        if (bk2 >= 0) {
          highp float d2 = sqrt(best2);
          highp float hb = clamp(0.5 + 0.5 * (d2 - d) / sk, 0.0, 1.0);
          highp float dS = mix(d2, d, hb) - sk * hb * (1.0 - hb);
          if (exShaped && !kExCutOn) {
            highp vec2 exF0 = gapOverPt(t4, t9, bk2);
            highp vec2 exF1 = gapOverPt(t4, t9, bk2 + 1);
            highp vec2 exFab = exF1 - exF0;
            highp float exFbl = dot(exFab, exFab);
            highp float exFbt = exFbl > 1e-12 ? clamp(dot(p - exF0, exFab) / exFbl, 0.0, 1.0) : 0.0;
            highp float exA2 = (t4.z + (float(bk2) + exFbt) * t9.x) * t4.w;
            bool exSaveOn = kExCutOn;
            highp float exSaveSd = kExCutSd;
            highp float exCoverFar = exploreCutCover(row, fl, exA2, d2, pxW);
            kExCutOn = exSaveOn;
            kExCutSd = exSaveSd;
            highp float exGN = exCutAtDist(d, hO, margin, fadeP, pxW, winM, t8.y, inWin * inFoot, fan);
            highp float exGF = exCutAtDist(d2, hO, margin, fadeP, pxW, winM, t8.y, inWin * inFoot, fan);
            highp float exGS = exCutAtDist(dS, hO, margin, fadeP, pxW, winM, t8.y, inWin * inFoot, fan);
            exBlendCut = max(exCoverNear * exGN, exCoverFar * exGF)
              + min(exCoverNear, exCoverFar) * (exGS - max(exGN, exGF));
            exFarOn = true;
          } else {
            d = dS;
          }
        }
      }
    }
    if (exShaped && kExCutOn) d = hO + kExCutSd;
    highp float e = d - hO - margin;
    highp float k = clamp((e + 0.5 * pxW) / max(fadeP, pxW), 0.0, 1.0);
    k = k * k * (3.0 - 2.0 * k);
    // WINDOW-END FADE RAMP: where a window ends before the fade has run
    // out (twin midpoint split, neighbor clearance, the eye-wall limit),
    // the fade portion - never the casing - dissolves over the last half
    // fade of arc instead of being chopped by the window's straight end.
    highp float fs = clamp(winM / max(0.5 * t8.y, pxW), 0.0, 1.0);
    fs = mix(1.0, fs * fs * (3.0 - 2.0 * fs), clamp(e / pxW, 0.0, 1.0));
    highp float cut = full ? (1.0 - k) * inWin * inFoot * fs : 0.0;
    if (fan) {
      // The over silhouette, INSET one pixel so the AA ramp lands on the
      // over ribbon's opaque interior: a ramp centered on the silhouette
      // stacked on the ribbon's own MSAA edge let the backdrop through
      // (thin dark seams wherever a web met the over thread).
      cut = max(cut, 1.0 - clamp((d - hO + pxW) / pxW + 0.5, 0.0, 1.0));
    }
    if (exFarOn) { cut = exBlendCut; gst = exStrength; }
    keep = min(keep, 1.0 - cut * gst);
  }
  return keep;
}

// The band [-h, h] box-filtered over a pixel of width p.
float bandCover(float u, float h, float p) {
  return clamp((min(u + 0.5 * p, h) - max(u - 0.5 * p, -h)) / p, 0.0, 1.0);
}

void main(void) {
  // Derivatives first, in uniform control flow (gap_mask.ts).
  vec2 gfw = fwidth(vPos);
  float pxW = max(max(gfw.x, gfw.y), 1e-5);
  float p = max(length(vec2(dFdx(vLat), dFdy(vLat))), 1e-4);
  float c = bandCover(vLat, uPluck.x, p) * vA;
  // K797b/K798 THREAD LOOK for a still pluck: in border mode (and while
  // a border-at-a-time intro is running) the white cue follows only the
  // two edge strokes; in both mode it leaves the dark strokes standing.
  bool lookBorder = uKLook.x > 0.5 && uKLook.x < 1.5;
  bool lookIntro = uKLook.y > 0.5 && uKLook.z > 0.5;
  float lookEdge = smoothstep(
    1.0 - uKLook.w,
    1.0 - uKLook.w + min(max(p / max(uPluck.x, 1e-4), 0.02), 0.38),
    abs(vLat) / max(uPluck.x, 1e-4));
  if (lookBorder || lookIntro) c *= lookEdge;
  if (c <= 0.002) discard;
  vec3 rgb = vec3(1.0);
  if (uKLook.x > 1.5 && !lookIntro) {
    rgb = mix(rgb, mix(vec3(0.09, 0.085, 0.08), uKBorder.rgb, uKBorder.w), lookEdge * 0.9);
  }
  float gk = gapKeepAt(pxW, vPos, vTurn, vTan, vMaskId);
  if (gk < 1.0 && gapProbe()) {
    rgb = mix(rgb, vec3(1.0, 0.0, 0.85), (1.0 - gk) * 0.75);
    gk = 1.0;
  }
  float a = c * gk;
  if (a <= 0.002) discard;
  finalColor = vec4(rgb, 1.0) * a * vColor;
}

