  v ^= v.yx >> 12u;
  v ^= v >> 16u;
  v *= uvec2(0xBE08065Fu, 0xE4E8B2D9u);
  v ^= v.yx >> 12u;
  v ^= v >> 14u;
  v *= uvec2(0xC3C8273Bu, 0xECD89725u);
