#version 300 es
#define SHADER_NAME bg-fog-vertex
precision highp float;

precision highp float;
in vec2 aPosition;
in vec2 aUV;
out vec2 vWorld;
out vec2 vScreen;
out float vPxPerWorld;
out vec4 vColor;

uniform mat3 uProjectionMatrix;
uniform mat3 uWorldTransformMatrix;
uniform vec4 uWorldColorAlpha;
uniform mat3 uTransformMatrix;
uniform vec4 uColor;

void main(void) {
  mat3 mv = uWorldTransformMatrix * uTransformMatrix;
  vec3 g = mv * vec3(aPosition, 1.0);
  gl_Position = vec4((uProjectionMatrix * g).xy, 0.0, 1.0);
  vWorld = aPosition;
  vScreen = g.xy;
  vPxPerWorld = length(vec2(mv[0][0], mv[0][1]));
  vColor = uColor * uWorldColorAlpha;
}
